fn build_execution_topology_shared_backend_summaries(
    execution: Option<&crate::schema::Execution>,
) -> Vec<ExecutionTopologySharedBackendSummary> {
    execution
        .map(|execution| {
            execution
                .shared_backends
                .iter()
                .map(
                    |(name, shared_backend)| ExecutionTopologySharedBackendSummary {
                        name: name.clone(),
                        scope: match shared_backend.scope {
                            crate::schema::ExecutionSharedBackendScope::Local => "local",
                            crate::schema::ExecutionSharedBackendScope::Remote => "remote",
                        }
                        .to_string(),
                        backend: format_backend(shared_backend.backend).to_string(),
                        lifecycle: format_lifecycle(shared_backend.lifecycle).to_string(),
                        context: shared_backend.context.clone(),
                        fulfillment: shared_backend.fulfillment.map(|fulfillment| {
                            match fulfillment {
                                crate::schema::ExecutionSharedBackendFulfillment::None => "none",
                                crate::schema::ExecutionSharedBackendFulfillment::Run => "run",
                            }
                            .to_string()
                        }),
                        environment: shared_backend.environment.as_ref().map(|environment| {
                            ExecutionTopologySharedBackendEnvironmentSummary {
                                profile: environment.profile.clone(),
                                image_alias: environment.image_alias.clone(),
                                image: environment.image.clone(),
                                source: environment.source.clone(),
                            }
                        }),
                    },
                )
                .collect()
        })
        .unwrap_or_default()
}

fn build_execution_topology_task_summary<'a>(
    name: &'a str,
    task: &'a TaskSpec,
    current_os: &str,
    contract: &'a Contract,
) -> ExecutionTopologyTaskSummary<'a> {
    ExecutionTopologyTaskSummary {
        task: TaskSummary::from_spec(name, task, current_os, contract),
        runtime: task
            .runtime
            .as_ref()
            .map(build_execution_topology_runtime_summary),
        targets: task
            .targets
            .iter()
            .map(|(target_name, target)| ExecutionTopologyTargetSummary {
                name: target_name.clone(),
                kind: match target.kind() {
                    crate::schema::TaskTargetKind::Service => "service",
                    crate::schema::TaskTargetKind::Url => "url",
                }
                .to_string(),
                override_input: target.override_input.clone(),
                url: target.url.clone(),
                activation_mode: target.activation.mode.as_str().to_string(),
                service: target.service.as_ref().map(|service| {
                    ExecutionTopologyTargetServiceSummary {
                        member: service.member.clone(),
                        task: service.task.clone(),
                        listener: service.listener.clone(),
                        address_view: match service.address_view {
                            crate::schema::TaskTargetAddressView::Topology => "topology",
                            crate::schema::TaskTargetAddressView::Host => "host",
                            crate::schema::TaskTargetAddressView::Internal => "internal",
                        }
                        .to_string(),
                    }
                }),
            })
            .collect(),
    }
}

fn build_execution_topology_runtime_summary(
    runtime: &crate::schema::TaskRuntimeSpec,
) -> ExecutionTopologyRuntimeSummary {
    ExecutionTopologyRuntimeSummary {
        kind: match runtime.kind {
            crate::schema::TaskRuntimeKind::Service => "service",
        }
        .to_string(),
        backend_binding: runtime.backend_binding.clone(),
        readiness: runtime
            .readiness
            .as_ref()
            .map(|readiness| ExecutionTopologyReadinessSummary {
                kind: match readiness.kind {
                    crate::schema::TaskRuntimeReadinessKind::Http => "http",
                    crate::schema::TaskRuntimeReadinessKind::Tcp => "tcp",
                }
                .to_string(),
                listener: readiness.listener.clone(),
                method: readiness.method.map(|method| method.as_str().to_string()),
                path: readiness.path.clone(),
                headers: readiness.headers.clone(),
                success: readiness.success.as_ref().map(|success| {
                    crate::output::ExecutionTopologyReadinessSuccessSummary {
                        status: success.status.clone(),
                    }
                }),
                body: readiness.body.as_ref().map(|body| {
                    crate::output::ExecutionTopologyReadinessBodySummary {
                        contains: body.contains.clone(),
                    }
                }),
                interval: readiness.interval.clone(),
                timeout: readiness.timeout.clone(),
                retries: readiness.retries,
                start_period: readiness.start_period.clone(),
            }),
        listeners: runtime
            .listeners
            .iter()
            .map(|(listener_name, listener)| {
                (
                    listener_name.clone(),
                    ExecutionTopologyListenerSummary {
                        protocol: match listener.protocol {
                            crate::schema::TaskRuntimeProtocol::Http => "http",
                            crate::schema::TaskRuntimeProtocol::Https => "https",
                            crate::schema::TaskRuntimeProtocol::Tcp => "tcp",
                        }
                        .to_string(),
                        bind_address: listener.bind.address.clone(),
                        bind_port_mode: match listener.bind.port.mode {
                            crate::schema::TaskRuntimePortMode::Fixed => "fixed",
                            crate::schema::TaskRuntimePortMode::Discover => "discover",
                            crate::schema::TaskRuntimePortMode::Auto => "auto",
                        }
                        .to_string(),
                        bind_port_value: listener.bind.port.value,
                        host_projection: listener.project.host.as_ref().map(|host| {
                            ExecutionTopologyHostProjectionSummary {
                                address: host.address.clone(),
                                port_mode: match host.port.mode {
                                    crate::schema::TaskRuntimeHostPortMode::Fixed => "fixed",
                                    crate::schema::TaskRuntimeHostPortMode::Auto => "auto",
                                }
                                .to_string(),
                                port_value: host.port.value,
                                primary: host.primary,
                                path: host.path.clone(),
                            }
                        }),
                    },
                )
            })
            .collect(),
    }
}

fn render_execution_topology_text(
    path: &str,
    contract_identity: &ContractIdentity,
    declared_execution: Option<&ExecutionSummary<'_>>,
    shared_backends: &[ExecutionTopologySharedBackendSummary],
    services: &[ServiceSummary],
    tasks: &[ExecutionTopologyTaskSummary<'_>],
) -> String {
    let mut output = format_command_header("EXECUTION TOPOLOGY", path);

    output.push_str("\n\n");
    output.push_str(&paint_section_title("Overview"));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Project:", "1;38;2;102;217;255"),
            &paint_code(&contract_identity.project.name),
        )
    ));
    if let Some(project_type) = contract_identity.project.project_type.as_deref() {
        output.push_str(&format!(
            "\n{}",
            section_list_row(
                &summary_bullet(),
                &paint("Type:", "1;38;2;102;217;255"),
                &paint_code(project_type),
            )
        ));
    }
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Services:", "1;38;2;102;217;255"),
            &paint(&services.len().to_string(), "1;38;2;255;255;255"),
        )
    ));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Tasks:", "1;38;2;102;217;255"),
            &paint(&tasks.len().to_string(), "1;38;2;255;255;255"),
        )
    ));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Shared Backends:", "1;38;2;102;217;255"),
            &paint(&shared_backends.len().to_string(), "1;38;2;255;255;255"),
        )
    ));

    if let Some(execution) = declared_execution {
        output.push_str("\n\n");
        output.push_str(&render_execution_summary_text(execution));
    }

    output.push_str(&render_execution_topology_shared_backends_text(
        shared_backends,
    ));
    output.push_str(&render_execution_topology_services_text(services));
    output.push_str(&render_execution_topology_tasks_text(tasks));
    output
}

fn render_execution_topology_shared_backends_text(
    shared_backends: &[ExecutionTopologySharedBackendSummary],
) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Shared Backends"));
    if shared_backends.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for shared_backend in shared_backends {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint(&shared_backend.name, "1")
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Scope:"),
            shared_backend.scope
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Backend:"),
            shared_backend.backend
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Lifecycle:"),
            shared_backend.lifecycle
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Context:"),
            shared_backend.context.as_deref().unwrap_or("-")
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Fulfillment:"),
            shared_backend.fulfillment.as_deref().unwrap_or("-")
        ));
        if let Some(environment) = shared_backend.environment.as_ref() {
            let mut details = Vec::new();
            if let Some(profile) = environment.profile.as_deref() {
                details.push(format!("profile={profile}"));
            }
            if let Some(image_alias) = environment.image_alias.as_deref() {
                details.push(format!("image_alias={image_alias}"));
            }
            if let Some(image) = environment.image.as_deref() {
                details.push(format!("image={image}"));
            }
            if let Some(source) = environment.source.as_deref() {
                details.push(format!("source={source}"));
            }
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Environment:"),
                if details.is_empty() {
                    String::from("-")
                } else {
                    details.join(", ")
                }
            ));
        }
    }

    output
}

fn render_execution_topology_services_text(services: &[ServiceSummary]) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Services"));
    if services.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for service in services {
        output.push_str(&format!(
            "\n\n{} {} [{}]",
            list_bullet(),
            paint(&service.name, "1"),
            if service.required {
                "required"
            } else {
                "optional"
            }
        ));
        let manager = service
            .manager
            .as_ref()
            .map(|manager| manager.kind.as_str())
            .or(service.provider.as_deref())
            .unwrap_or("-");
        output.push_str(&format!("\n  {} {manager}", paint_key("Manager:")));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Depends On:"),
            if service.depends_on.is_empty() {
                String::from("-")
            } else {
                service.depends_on.join(", ")
            }
        ));
        if let Some(readiness) = service.readiness.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Readiness:"),
                format_service_readiness_summary(readiness)
            ));
        }
        if !service.endpoints.is_empty() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Endpoints:"),
                service
                    .endpoints
                    .iter()
                    .map(|(context, endpoint)| {
                        format!("{context}=http://{}:{}", endpoint.address, endpoint.port)
                    })
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
    }

    output
}

fn render_execution_topology_tasks_text(tasks: &[ExecutionTopologyTaskSummary<'_>]) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Tasks"));
    if tasks.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for task in tasks {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint(task.task.name, "1")
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Context:"),
            task.task.context.unwrap_or("-")
        ));
        output.push_str(&format!("\n  {} {}", paint_key("Kind:"), task.task.kind));
        if let Some(runtime) = task.runtime.as_ref() {
            output.push_str(&format!("\n  {} {}", paint_key("Runtime:"), runtime.kind));
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Backend Binding:"),
                runtime.backend_binding.as_deref().unwrap_or("-")
            ));
            if let Some(readiness) = runtime.readiness.as_ref() {
                let mut readiness_detail = readiness.kind.clone();
                if let Some(listener) = readiness.listener.as_deref() {
                    readiness_detail.push_str(&format!(" via {listener}"));
                }
                if let Some(path) = readiness.path.as_deref() {
                    readiness_detail.push_str(&format!(" path={path}"));
                }
                output.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Readiness:"),
                    readiness_detail
                ));
            }
            if !runtime.listeners.is_empty() {
                output.push_str(&format!("\n  {}", paint_key("Listeners:")));
                for (listener_name, listener) in &runtime.listeners {
                    let mut bind_detail =
                        format!("{} {}", listener.bind_address, listener.bind_port_mode);
                    if let Some(value) = listener.bind_port_value {
                        bind_detail.push_str(&format!(":{value}"));
                    }
                    let mut listener_line =
                        format!("{listener_name} ({}, bind={bind_detail}", listener.protocol);
                    if let Some(host_projection) = listener.host_projection.as_ref() {
                        listener_line.push_str(&format!(
                            ", host={} {}",
                            host_projection.address, host_projection.port_mode
                        ));
                        if let Some(value) = host_projection.port_value {
                            listener_line.push_str(&format!(":{value}"));
                        }
                        if host_projection.primary {
                            listener_line.push_str(", primary");
                        }
                        if let Some(path) = host_projection.path.as_deref() {
                            listener_line.push_str(&format!(", path={path}"));
                        }
                    }
                    listener_line.push(')');
                    output.push_str(&format!("\n    {} {listener_line}", detail_arrow()));
                }
            }
        }
        if !task.targets.is_empty() {
            output.push_str(&format!("\n  {}", paint_key("Targets:")));
            for target in &task.targets {
                let target_line = if let Some(service) = target.service.as_ref() {
                    let mut service_ref = String::new();
                    if let Some(member) = service.member.as_deref() {
                        service_ref.push_str(&format!("{member}."));
                    }
                    service_ref.push_str(&service.task);
                    if let Some(listener) = service.listener.as_deref() {
                        service_ref.push_str(&format!(".{listener}"));
                    }
                    format!(
                        "{} ({}, activation={}, view={})",
                        target.name, service_ref, target.activation_mode, service.address_view
                    )
                } else {
                    format!(
                        "{} (url={}, activation={})",
                        target.name,
                        target.url.as_deref().unwrap_or("-"),
                        target.activation_mode
                    )
                };
                output.push_str(&format!("\n    {} {target_line}", detail_arrow()));
            }
        }
    }

    output
}

pub fn studio(
    path: Option<&Path>,
    file_override: Option<&Path>,
    open: bool,
    serve: bool,
    member: Option<&str>,
    debug: bool,
) -> CommandOutput {
    let repo_root = studio_repo_root(path, file_override);
    let compact_repo_display = compact_repo_path(&repo_root);
    let path_display = repo_root.display().to_string();
    let mut debug_lines = vec![
        String::from("DEBUG command=studio"),
        format!("DEBUG repo_root={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    debug_lines.push(format!("DEBUG open={open}"));
    debug_lines.push(format!("DEBUG serve={serve}"));
    if let Some(file_override) = file_override {
        debug_lines.push(format!("DEBUG file_override={}", file_override.display()));
    }

    finalize_debug(
        if serve {
            serve_studio(
                path,
                file_override,
                member,
                &repo_root,
                &compact_repo_display,
                open,
            )
        } else {
            match write_studio_snapshot(
                path,
                file_override,
                member,
                &repo_root,
                StudioSnapshotMode::ReadOnlySnapshot,
                None,
            ) {
                Ok(report) => {
                    if open {
                        if let Err(error) =
                            open_studio_target_in_browser(report.output_path.display().to_string())
                        {
                            CommandOutput::failure(format!(
                                "studio snapshot exported to `{}` but could not be opened automatically: {error}",
                                report.output_path.display()
                            ))
                        } else {
                            CommandOutput::success(render_studio_export_text(
                                &compact_repo_display,
                                member,
                                &report.output_path,
                                report.contract_path.as_deref(),
                                None,
                                false,
                                true,
                            ))
                        }
                    } else {
                        CommandOutput::success(render_studio_export_text(
                            &compact_repo_display,
                            member,
                            &report.output_path,
                            report.contract_path.as_deref(),
                            None,
                            false,
                            false,
                        ))
                    }
                }
                Err(error) => CommandOutput::failure(error),
            }
        },
        debug,
        debug_lines,
    )
}

struct StudioSnapshotReport {
    output_path: PathBuf,
    contract_path: Option<PathBuf>,
}

#[derive(Clone, Copy)]
enum StudioSnapshotMode {
    ReadOnlySnapshot,
    InteractiveServer,
}

impl StudioSnapshotMode {
    fn as_str(self) -> &'static str {
        match self {
            Self::ReadOnlySnapshot => "read_only_snapshot",
            Self::InteractiveServer => "interactive_server",
        }
    }
}

#[derive(Clone, Copy)]
enum StudioAction {
    Starter,
    Merge,
}

impl StudioAction {
    fn label(self) -> &'static str {
        match self {
            Self::Starter => "starter",
            Self::Merge => "merge",
        }
    }
}

fn studio_snapshot_payload(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    repo_root: &Path,
    mode: StudioSnapshotMode,
    action_base_url: Option<&str>,
) -> Result<(JsonValue, Option<PathBuf>), String> {
    let contract_path = resolve_contract_path(path, file_override).ok();
    let contract_text = contract_path
        .as_ref()
        .and_then(|path| fs::read_to_string(path).ok());
    let review_contracts = studio_review_contracts(repo_root, contract_path.as_deref())?;
    let activity = studio_recent_activity_payload(repo_root, contract_path.as_deref());
    let member_args = member
        .map(|value| vec![value.to_string()])
        .unwrap_or_default();
    let doctor_json = studio_command_json_value(doctor(
        Some(repo_root),
        file_override,
        &member_args,
        false,
        false,
        crate::doctor::DoctorMode::Native,
        OutputFormat::Json,
        false,
    ))?;
    let detect_json = studio_command_json_value(detect(
        Some(repo_root),
        false,
        true,
        false,
        false,
        &[],
        false,
        false,
        false,
        OutputFormat::Json,
        false,
    ))?;
    let detect_contract_text = detect_json
        .get("config")
        .cloned()
        .and_then(|value| serde_yaml::to_string(&value).ok());
    let topology_json = if contract_path.is_some() {
        studio_command_json_value(execution_topology(
            Some(repo_root),
            file_override,
            member,
            OutputFormat::Json,
            false,
        ))?
    } else {
        json!({
            "ok": false,
            "path": repo_root.display().to_string(),
            "member": member,
            "error": "execution topology requires a valid ota.yaml; start with `ota doctor` or `ota detect --dry-run .`"
        })
    };

    Ok((
        json!({
            "studio": {
                "version": env!("CARGO_PKG_VERSION"),
                "mode": mode.as_str(),
                "member": member,
                "repo_root": repo_root.display().to_string(),
                "contract_path": contract_path.as_ref().map(|value| value.display().to_string()),
                "generated_at": OffsetDateTime::now_utc()
                    .format(&format_description!("[year]-[month]-[day]T[hour]:[minute]:[second]Z"))
                    .unwrap_or_else(|_| String::from("unknown")),
                "action_base_url": action_base_url,
            },
            "contract_text": contract_text,
            "detect_contract_text": detect_contract_text,
            "review_contracts": review_contracts,
            "activity": activity,
            "doctor": {
                "exit_code": if doctor_json["ok"].as_bool() == Some(true) { 0 } else { 1 },
                "data": doctor_json,
            },
            "detect": {
                "exit_code": if detect_json["ok"].as_bool() == Some(true) { 0 } else { 1 },
                "data": detect_json,
            },
            "topology": {
                "exit_code": if topology_json["ok"].as_bool() == Some(true) { 0 } else { 1 },
                "data": topology_json,
            }
        }),
        contract_path,
    ))
}

fn studio_recent_activity_payload(repo_root: &Path, contract_path: Option<&Path>) -> JsonValue {
    let scan = match scan_repo_receipt_archives(repo_root) {
        Ok(scan) => scan,
        Err(error) => {
            return json!({
                "entries": [],
                "invalid_archive_count": 0,
                "error": error,
            });
        }
    };

    let current_identity =
        contract_path.map(|path| repo_receipt_contract_identity(repo_root, path));
    let entries = scan
        .archives
        .iter()
        .take(5)
        .map(|record| {
            let receipt = &record.payload.receipt;
            json!({
                "archived_at": record.archived_at,
                "ok": record.payload.ok,
                "contract": receipt.contract,
                "status": receipt.status,
                "backend": receipt.backend,
                "context": receipt.context,
                "lifecycle": receipt.lifecycle,
                "target": receipt.target,
                "provider": receipt.provider,
                "cwd": receipt.cwd,
                "failed_task": receipt.failed_task,
                "failed_dependency": receipt.failed_dependency,
                "failure_origin": receipt.failure_origin,
                "next": receipt.next,
                "summary": record.payload.summary,
                "logs": receipt.logs,
                "steps": receipt.steps,
                "findings": record.payload.findings,
                "matches_current_contract": current_identity.as_deref().is_none_or(|identity| {
                    repo_receipt_contract_identity_from_archive_record(record).as_deref()
                        == Some(identity)
                }),
            })
        })
        .collect::<Vec<_>>();

    json!({
        "contract_identity": current_identity,
        "history_count": scan.archives.len(),
        "invalid_archive_count": scan.invalid_archives.len(),
        "entries": entries,
    })
}

fn studio_review_contracts(
    repo_root: &Path,
    contract_path: Option<&Path>,
) -> Result<JsonValue, String> {
    let report = detect_repo(repo_root).map_err(|error| error.to_string())?;
    let rewrite_contract_text = studio_rewrite_contract_text(&report).ok();
    let Some(contract_path) = contract_path else {
        return Ok(json!({
            "rewrite_contract_text": rewrite_contract_text,
        }));
    };

    let (merge_contract_text, error) = match load_contract(contract_path) {
        Ok(existing_contract) => {
            let comparison =
                build_detect_comparison(&existing_contract, &report, DetectRemovalScope::Drift);
            match studio_merge_contract_text(contract_path, &report, &comparison) {
                Ok(text) => (Some(text), None),
                Err(error) => (None, Some(error)),
            }
        }
        Err(error) => (None, Some(error.to_string())),
    };
    Ok(json!({
        "merge_contract_text": merge_contract_text,
        "rewrite_contract_text": rewrite_contract_text,
        "error": error,
    }))
}

fn studio_merge_contract_text(
    contract_path: &Path,
    report: &DetectReport,
    comparison: &DetectComparison,
) -> Result<String, String> {
    let contents = fs::read_to_string(contract_path).map_err(|error| {
        format!(
            "failed to read existing contract `{}` for Studio merge preview: {error}",
            compact_contract_path(contract_path)
        )
    })?;
    let mut document: YamlValue = serde_yaml::from_str(&contents).map_err(|error| {
        format!(
            "failed to parse existing contract `{}` for Studio merge preview: {error}",
            compact_contract_path(contract_path)
        )
    })?;
    let high_confidence_fields = detect_high_confidence_inference_fields(&report.inferences)
        .into_iter()
        .collect::<BTreeSet<_>>();
    let mut applied_fields = Vec::new();
    for change in comparison
        .changes
        .iter()
        .filter(|change| change.status == "add" || change.status == "update")
    {
        if !detect_change_is_high_confidence(change, &high_confidence_fields) {
            continue;
        }
        if apply_detect_change(&mut document, change) {
            applied_fields.push(change.field.clone());
        }
    }
    record_detect_owned_fields(&mut document, applied_fields)?;
    serde_yaml::to_string(&document).map_err(|error| {
        format!(
            "failed to serialize Studio merge preview for `{}`: {error}",
            compact_contract_path(contract_path)
        )
    })
}

fn studio_rewrite_contract_text(report: &DetectReport) -> Result<String, String> {
    let mut document = serde_yaml::to_value(&report.contract)
        .map_err(|error| format!("failed to serialize Studio rewrite preview: {error}"))?;
    record_detect_owned_fields(&mut document, detect_field_paths(&report.contract))?;
    serde_yaml::to_string(&document)
        .map_err(|error| format!("failed to render Studio rewrite preview: {error}"))
}

fn write_studio_snapshot(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    repo_root: &Path,
    mode: StudioSnapshotMode,
    action_base_url: Option<&str>,
) -> Result<StudioSnapshotReport, String> {
    ensure_ota_state_gitignored(repo_root)?;

    let output_path = repo_root.join(".ota/state/studio/index.html");
    let (snapshot, contract_path) = studio_snapshot_payload(
        path,
        file_override,
        member,
        repo_root,
        mode,
        action_base_url,
    )?;
    let html = render_studio_snapshot_html(&snapshot);
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("failed to create `{}`: {error}", parent.display()))?;
    }
    fs::write(&output_path, html)
        .map_err(|error| format!("failed to write `{}`: {error}", output_path.display()))?;

    Ok(StudioSnapshotReport {
        output_path,
        contract_path,
    })
}

fn serve_studio(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    repo_root: &Path,
    compact_repo_display: &str,
    open: bool,
) -> CommandOutput {
    let listener = match TcpListener::bind(("127.0.0.1", 0)) {
        Ok(listener) => listener,
        Err(error) => {
            return CommandOutput::failure(format!(
                "failed to start Studio server on localhost: {error}"
            ));
        }
    };
    let port = match listener.local_addr() {
        Ok(addr) => addr.port(),
        Err(error) => {
            return CommandOutput::failure(format!(
                "studio server started but local address could not be determined: {error}"
            ));
        }
    };
    let url = format!("http://127.0.0.1:{port}/");
    let report = match write_studio_snapshot(
        path,
        file_override,
        member,
        repo_root,
        StudioSnapshotMode::InteractiveServer,
        Some(&url),
    ) {
        Ok(report) => report,
        Err(error) => return CommandOutput::failure(error),
    };
    if open && let Err(error) = open_studio_target_in_browser(url.clone()) {
        return CommandOutput::failure(format!(
            "studio server started on `{url}` but could not be opened automatically: {error}"
        ));
    }

    let rendered = render_studio_export_text(
        compact_repo_display,
        member,
        &report.output_path,
        report.contract_path.as_deref(),
        Some(&url),
        true,
        open,
    );
    println!("{rendered}");
    let _ = io::stdout().flush();

    if let Err(error) = listener.set_nonblocking(true) {
        return CommandOutput::failure(format!(
            "studio server started on `{url}` but could not switch to nonblocking mode: {error}"
        ));
    }
    let stop = Arc::new(AtomicBool::new(false));
    if let Err(error) = signal_flag::register(SIGINT, Arc::clone(&stop)) {
        return CommandOutput::failure(format!(
            "studio server started on `{url}` but could not register SIGINT handler: {error}"
        ));
    }
    if let Err(error) = signal_flag::register(SIGTERM, Arc::clone(&stop)) {
        return CommandOutput::failure(format!(
            "studio server started on `{url}` but could not register SIGTERM handler: {error}"
        ));
    }

    while !stop.load(Ordering::Relaxed) {
        match listener.accept() {
            Ok((mut stream, _)) => {
                let _ = handle_studio_server_request(
                    &mut stream,
                    path,
                    file_override,
                    member,
                    repo_root,
                    &report.output_path,
                    &url,
                );
            }
            Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
                thread::sleep(Duration::from_millis(80));
            }
            Err(error) => {
                eprintln!("studio server stopped after accept error: {error}");
                break;
            }
        }
    }

    CommandOutput::success(String::new())
}

fn handle_studio_server_request(
    stream: &mut TcpStream,
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    repo_root: &Path,
    output_path: &Path,
    url: &str,
) -> Result<(), String> {
    let (method, request_path) = read_http_request_head(stream)?;
    match (method.as_str(), request_path.as_str()) {
        ("GET", "/") | ("GET", "/index.html") => {
            let body = fs::read(output_path).map_err(|error| {
                format!(
                    "failed to read Studio snapshot `{}`: {error}",
                    compact_path(output_path, "index.html")
                )
            })?;
            write_http_response(stream, 200, "OK", "text/html; charset=utf-8", &body)
        }
        ("GET", "/api/snapshot") => {
            let (snapshot, _contract_path) = studio_snapshot_payload(
                path,
                file_override,
                member,
                repo_root,
                StudioSnapshotMode::InteractiveServer,
                Some(url),
            )?;
            write_http_json(stream, &snapshot)
        }
        ("POST", "/api/actions/init") => {
            let payload = studio_apply_action(StudioAction::Starter, repo_root);
            if payload["ok"].as_bool() == Some(true) {
                let _ = write_studio_snapshot(
                    path,
                    file_override,
                    member,
                    repo_root,
                    StudioSnapshotMode::InteractiveServer,
                    Some(url),
                );
            }
            write_http_json(stream, &payload)
        }
        ("POST", "/api/actions/merge") => {
            let payload = studio_apply_action(StudioAction::Merge, repo_root);
            if payload["ok"].as_bool() == Some(true) {
                let _ = write_studio_snapshot(
                    path,
                    file_override,
                    member,
                    repo_root,
                    StudioSnapshotMode::InteractiveServer,
                    Some(url),
                );
            }
            write_http_json(stream, &payload)
        }
        _ => write_http_response(
            stream,
            404,
            "Not Found",
            "application/json; charset=utf-8",
            br#"{"ok":false,"error":"not found"}"#,
        ),
    }
}

fn studio_apply_action(action: StudioAction, repo_root: &Path) -> JsonValue {
    let output = match action {
        StudioAction::Starter => init(
            Some(repo_root),
            true,
            false,
            None,
            false,
            OutputFormat::Json,
            false,
        ),
        StudioAction::Merge => detect(
            Some(repo_root),
            true,
            false,
            false,
            true,
            &[],
            true,
            false,
            false,
            OutputFormat::Json,
            false,
        ),
    };
    match studio_command_json_value(output) {
        Ok(mut payload) => {
            if payload.get("ok").is_none() {
                payload["ok"] = JsonValue::Bool(false);
            }
            payload["action"] = JsonValue::String(action.label().to_string());
            payload
        }
        Err(error) => json!({
            "ok": false,
            "action": action.label(),
            "error": error,
        }),
    }
}

fn read_http_request_head(stream: &mut TcpStream) -> Result<(String, String), String> {
    let mut buffer = [0u8; 4096];
    let bytes_read = stream
        .read(&mut buffer)
        .map_err(|error| format!("failed to read studio request: {error}"))?;
    let request = String::from_utf8_lossy(&buffer[..bytes_read]);
    let mut lines = request.lines();
    let request_line = lines
        .next()
        .ok_or_else(|| String::from("studio request was empty"))?;
    let mut parts = request_line.split_whitespace();
    let method = parts
        .next()
        .ok_or_else(|| String::from("studio request is missing method"))?;
    let path = parts
        .next()
        .ok_or_else(|| String::from("studio request is missing path"))?;
    Ok((method.to_string(), path.to_string()))
}

fn write_http_json(stream: &mut TcpStream, payload: &JsonValue) -> Result<(), String> {
    let body = serde_json::to_vec(payload)
        .map_err(|error| format!("failed to serialize studio action response: {error}"))?;
    write_http_response(stream, 200, "OK", "application/json; charset=utf-8", &body)
}

fn write_http_response(
    stream: &mut TcpStream,
    status_code: u16,
    status_text: &str,
    content_type: &str,
    body: &[u8],
) -> Result<(), String> {
    let headers = format!(
        "HTTP/1.1 {status_code} {status_text}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    stream
        .write_all(headers.as_bytes())
        .and_then(|_| stream.write_all(body))
        .and_then(|_| stream.flush())
        .map_err(|error| format!("failed to write studio response: {error}"))
}

fn studio_repo_root(path: Option<&Path>, file_override: Option<&Path>) -> PathBuf {
    match file_override.or(path) {
        Some(path) if path.is_file() => contract_working_dir(path).to_path_buf(),
        Some(path) => path.to_path_buf(),
        None => PathBuf::from("."),
    }
}

fn studio_command_json_value(output: CommandOutput) -> Result<JsonValue, String> {
    let body = if !output.stdout.trim().is_empty() {
        output.stdout
    } else if let Some(stderr) = output.stderr {
        stderr
    } else {
        return Err(String::from(
            "studio snapshot command produced no JSON output",
        ));
    };

    serde_json::from_str(&body)
        .map_err(|error| format!("studio snapshot could not parse command JSON output: {error}"))
}

fn open_studio_target_in_browser(target: String) -> Result<(), String> {
    #[cfg(target_os = "macos")]
    let mut command = {
        let mut command = Command::new("open");
        command.arg(&target);
        command
    };

    #[cfg(target_os = "windows")]
    let mut command = {
        let mut command = Command::new("cmd");
        command.arg("/C").arg("start").arg("").arg(&target);
        command
    };

    #[cfg(all(not(target_os = "macos"), not(target_os = "windows")))]
    let mut command = {
        let mut command = Command::new("xdg-open");
        command.arg(&target);
        command
    };

    let status = command
        .status()
        .map_err(|error| format!("failed to launch browser opener: {error}"))?;
    if status.success() {
        Ok(())
    } else {
        Err(format!("browser opener exited with status {status}"))
    }
}

fn render_studio_export_text(
    path: &str,
    member: Option<&str>,
    output_path: &Path,
    contract_path: Option<&Path>,
    serve_url: Option<&str>,
    interactive: bool,
    opened: bool,
) -> String {
    let display = display_contract_target(path, member);
    let mut output = format!(
        "{}\n\n{}",
        format_command_header("STUDIO", &display),
        render_named_status("EXPORTED", String::from("✓"), "1;38;2;125;255;212")
    );
    output.push_str(&format!("\n\n{}", paint_section_title("Overview")));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Mode:", "1;38;2;102;217;255"),
            &paint(
                if interactive {
                    "interactive local server"
                } else {
                    "read-only snapshot"
                },
                "1;38;2;255;255;255"
            ),
        )
    ));
    if let Some(serve_url) = serve_url {
        output.push_str(&format!(
            "\n{}",
            section_list_row(
                &summary_bullet(),
                &paint("Serve:", "1;38;2;102;217;255"),
                &paint_code(serve_url),
            )
        ));
    }
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Output:", "1;38;2;102;217;255"),
            &paint_code(&compact_path(output_path, "index.html")),
        )
    ));
    if let Some(contract_path) = contract_path {
        output.push_str(&format!(
            "\n{}",
            section_list_row(
                &summary_bullet(),
                &paint("Contract:", "1;38;2;102;217;255"),
                &paint_code(&compact_contract_path(contract_path)),
            )
        ));
    }
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Data:", "1;38;2;102;217;255"),
            &paint("doctor, detect, execution topology", "1;38;2;255;255;255"),
        )
    ));
    let next_steps = if opened {
        if interactive {
            vec![
                String::from(
                    "opened Studio in your default browser with reviewed write actions enabled",
                ),
                String::from("press Ctrl-C to stop the local Studio server"),
                String::from("rerun `ota studio --serve --open` after repo or contract changes"),
            ]
        } else {
            vec![
                format!("opened `{}` in your default browser", output_path.display()),
                String::from("rerun `ota studio --open` after repo or contract changes"),
            ]
        }
    } else {
        if interactive {
            vec![
                format!(
                    "open `{}` in a browser to review and apply safe changes",
                    serve_url.unwrap_or("http://127.0.0.1")
                ),
                String::from(
                    "rerun `ota studio --serve --open` to launch the interactive Studio path directly",
                ),
                String::from("press Ctrl-C to stop the local Studio server"),
            ]
        } else {
            vec![
                format!("open `{}` in a browser", output_path.display()),
                String::from("rerun `ota studio --open` to export and open it automatically"),
                String::from("rerun `ota studio` after repo or contract changes"),
            ]
        }
    };
    output.push_str(&format_next_timeline(&next_steps));
    output
}

fn execution_plan_overrides(overrides: ExecutionOverrides) -> Option<ExecutionPlanOverrides> {
    let overrides = ExecutionPlanOverrides {
        backend: overrides.backend.map(format_backend).map(str::to_string),
        lifecycle: overrides
            .lifecycle
            .map(format_lifecycle)
            .map(str::to_string),
    };

    if overrides.backend.is_none() && overrides.lifecycle.is_none() {
        None
    } else {
        Some(overrides)
    }
}

fn execution_plan_error(error: &RunError) -> String {
    match error {
        RunError::MissingContainerImage { .. } => String::from(
            "`ota execution plan` requires `execution.backends.container.image` for container execution",
        ),
        RunError::MissingContainerLifecycle { .. } => String::from(
            "`ota execution plan` requires an explicit `execution.lifecycle` for container execution",
        ),
        RunError::MissingContainerBackendCli { engines, .. } => format!(
            "container execution requires one of the supported container backend CLIs on PATH: {engines}"
        ),
        RunError::MissingRemoteProvider { .. } => String::from(
            "`ota execution plan` requires `execution.backends.remote.provider` for remote execution",
        ),
        RunError::MissingRemoteTarget {
            provider,
            example_target,
            ..
        } => format!(
            "remote provider `{provider}` requires `execution.backends.remote.target` (example: `{example_target}`)"
        ),
        RunError::MissingBackendProvider { provider, .. } => format!(
            "remote provider `{provider}` is not declared as a backend provider in ota.yaml"
        ),
        RunError::UnsupportedBackendProviderVersion {
            provider,
            api_version,
            ..
        } => format!(
            "backend provider `{provider}` has unsupported `api_version` `{api_version}`; expected `1`"
        ),
        other => other.to_string(),
    }
}

fn execution_backend_resolution_lines(
    contract: &Contract,
    overrides: ExecutionOverrides,
    task_name: Option<&str>,
    backend: Backend,
) -> Vec<String> {
    let backend_label = format_backend(backend);
    let backend_flag = format!("--mode {backend_label}");
    if overrides.backend == Some(backend) {
        let subject = task_name
            .map(|task| format!("task `{task}`"))
            .unwrap_or_else(|| String::from("execution inspection"));
        return vec![format!("{subject} was requested with `{backend_flag}`")];
    }

    if contract
        .execution
        .as_ref()
        .and_then(|execution| execution.preferred)
        == Some(backend)
    {
        let subject = task_name
            .map(|task| format!("task `{task}`"))
            .unwrap_or_else(|| String::from("execution inspection"));
        return vec![
            format!("{subject} resolves to {backend_label} execution by default"),
            format!("this contract sets `execution.preferred: {backend_label}`"),
        ];
    }
    if let Some(task_name) = task_name
        && contract
            .tasks
            .get(task_name)
            .and_then(|task| task.mode_default_backend())
            == Some(backend)
    {
        return vec![
            format!("task `{task_name}` resolves to {backend_label} execution by default"),
            format!("this task sets `tasks.{task_name}.execution.default_mode: {backend_label}`"),
        ];
    }

    let subject = task_name
        .map(|task| format!("task `{task}`"))
        .unwrap_or_else(|| String::from("execution inspection"));
    vec![format!("{subject} resolved to {backend_label} execution")]
}

fn render_execution_plan_structured_error(
    contract: &Contract,
    contract_path: &Path,
    member: Option<&str>,
    overrides: ExecutionOverrides,
    error: &RunError,
) -> String {
    let text_path_display = display_contract_target(&compact_contract_path(contract_path), member);
    let (summary, mut why_lines, next_steps) = match error {
        RunError::MissingContainerImage { .. } => (
            "Container execution is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Container),
            vec![
                String::from("add `execution.backends.container.image` to the repo contract"),
                String::from(
                    "or rerun without container mode if this inspection should stay on the host",
                ),
            ],
        ),
        RunError::MissingContainerLifecycle { .. } => (
            "Container execution lifecycle is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Container),
            vec![
                String::from("add `execution.lifecycle` to the repo contract"),
                String::from(
                    "or rerun without container mode if this inspection should stay on the host",
                ),
            ],
        ),
        RunError::MissingContainerBackendCli { engines, .. } => (
            "Missing container execution backend CLI",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Container),
            vec![
                format!("install one of the supported container engines: `{engines}`"),
                String::from(
                    "or rerun without container mode if this inspection should stay on the host",
                ),
            ],
        ),
        RunError::MissingRemoteProvider { .. } => (
            "Remote execution is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Remote),
            vec![
                String::from("add `execution.backends.remote.provider` to the repo contract"),
                String::from("or rerun without remote mode if this inspection should stay local"),
            ],
        ),
        RunError::MissingRemoteTarget {
            provider,
            example_target,
            ..
        } => (
            "Remote execution target is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Remote),
            vec![
                format!(
                    "add `execution.backends.remote.target` for provider `{provider}` (for example `{example_target}`)"
                ),
                String::from("or rerun without remote mode if this inspection should stay local"),
            ],
        ),
        RunError::MissingBackendProvider { provider, .. } => (
            "Backend provider is not configured",
            vec![format!(
                "execution inspection requested backend provider `{provider}`, but the repo does not declare it"
            )],
            vec![format!(
                "declare backend provider `{provider}` in the repo contract or rerun with a supported built-in backend"
            )],
        ),
        RunError::UnsupportedBackendProviderVersion {
            provider,
            api_version,
            ..
        } => (
            "Backend provider version is unsupported",
            vec![format!(
                "backend provider `{provider}` declares unsupported `api_version` `{api_version}`; expected `1`"
            )],
            vec![String::from(
                "update the backend provider declaration to `api_version: 1`, then rerun `ota execution plan`",
            )],
        ),
        _ => (
            "Execution plan could not be resolved",
            vec![execution_plan_error(error)],
            vec![String::from(
                "repair the declared execution settings, then rerun `ota execution plan`",
            )],
        ),
    };

    if matches!(
        error,
        RunError::MissingContainerImage { .. }
            | RunError::MissingContainerLifecycle { .. }
            | RunError::MissingContainerBackendCli { .. }
    ) {
        why_lines.push(match error {
            RunError::MissingContainerImage { .. } => {
                String::from("this contract does not declare `execution.backends.container.image`")
            }
            RunError::MissingContainerLifecycle { .. } => {
                String::from("this contract does not declare `execution.lifecycle`")
            }
            RunError::MissingContainerBackendCli { engines, .. } => {
                format!("no supported container engine is available on PATH: {engines}")
            }
            _ => unreachable!(),
        });
    } else if matches!(error, RunError::MissingRemoteProvider { .. }) {
        why_lines.push(String::from(
            "this contract does not declare `execution.backends.remote.provider`",
        ));
    } else if matches!(error, RunError::MissingRemoteTarget { .. }) {
        why_lines.push(String::from(
            "this contract does not declare `execution.backends.remote.target`",
        ));
    }

    structured_error_text(
        "EXECUTION PLAN",
        &text_path_display,
        summary,
        &why_lines,
        &next_steps,
    )
}

fn resolve_execution_plan(
    contract: &Contract,
    contract_path: &Path,
    overrides: ExecutionOverrides,
) -> Result<ExecutionPlanResolved, RunError> {
    let task_name = "execution plan";
    let (backend, lifecycle) = effective_execution(contract, overrides);
    let effective = effective_task_execution(contract, task_name, overrides);
    let execution = contract.execution.as_ref();
    let backend_source = if overrides.backend.is_some() {
        "override"
    } else if execution
        .and_then(|execution| execution.default_context.as_deref())
        .is_some_and(|name| effective.context_name == Some(name))
    {
        "default context"
    } else if contract
        .execution
        .as_ref()
        .and_then(|execution| execution.preferred)
        .is_some()
    {
        "contract preferred"
    } else {
        "default"
    };
    let mut lifecycle_source = if overrides.lifecycle.is_some() {
        String::from("override")
    } else if execution
        .and_then(|execution| execution.default_context.as_deref())
        .is_some_and(|name| effective.context_name == Some(name) && effective.lifecycle.is_some())
    {
        String::from("context lifecycle")
    } else if contract
        .execution
        .as_ref()
        .and_then(|execution| execution.lifecycle)
        .is_some()
    {
        String::from("contract lifecycle")
    } else {
        String::from("implicit")
    };
    let planned_container_image = if backend == Backend::Container {
        resolve_execution_plan_container_image(
            contract,
            contract_path,
            task_name,
            effective.context_name,
            effective.lifecycle,
            effective
                .container
                .map(|container| container.image.as_str()),
        )?
    } else {
        None
    };
    let resolved_backend = match resolve_execution_backend_with_contract_path(
        contract,
        task_name,
        overrides,
        Some(contract_path),
    ) {
        Ok(resolved_backend) => Ok(resolved_backend),
        Err(RunError::MissingContainerBackendCli { .. }) if backend == Backend::Container => {
            let (container, image, _) = resolve_effective_task_container_backend(
                contract,
                task_name,
                overrides,
                Some(contract_path),
            )?;
            let lifecycle =
                effective
                    .lifecycle
                    .ok_or_else(|| RunError::MissingContainerLifecycle {
                        task: task_name.to_string(),
                    })?;
            let target = match lifecycle {
                Lifecycle::Persistent => {
                    execution_target(contract, contract_path, backend, Some(lifecycle))
                }
                Lifecycle::Ephemeral => ephemeral_container_target(contract, contract_path),
            };
            let target_strategy = match lifecycle {
                Lifecycle::Persistent => String::from("persistent container"),
                Lifecycle::Ephemeral => String::from("ephemeral per-run container"),
            };
            return Ok(ExecutionPlanResolved {
                backend: format_backend(backend).to_string(),
                backend_source: String::from(backend_source),
                lifecycle: Some(format_lifecycle(lifecycle).to_string()),
                lifecycle_source: Some(lifecycle_source),
                image: Some(planned_container_image.unwrap_or(image)),
                engine: selected_container_engine_from_backend(Some(&container)),
                engine_candidates: container_engine_candidates_from_backend(Some(&container)),
                provider: None,
                target,
                target_strategy,
                cwd: None,
            });
        }
        Err(error) => Err(error),
    }?;

    let resolved_lifecycle = match &resolved_backend {
        ResolvedExecutionBackend::Container { lifecycle, .. } => Some(*lifecycle),
        _ => lifecycle,
    };
    if backend == Backend::Container
        && resolved_lifecycle.is_some()
        && overrides.lifecycle.is_none()
        && contract
            .execution
            .as_ref()
            .and_then(|execution| execution.lifecycle)
            .is_none()
    {
        lifecycle_source = String::from("context lifecycle");
    }
    let lifecycle_source = resolved_lifecycle.map(|_| lifecycle_source.clone());

    let (image, engine, engine_candidates, provider, target, target_strategy, cwd) =
        match resolved_backend {
            ResolvedExecutionBackend::Native { .. } => (
                None,
                None,
                Vec::new(),
                None,
                None,
                String::from("host process"),
                None,
            ),
            ResolvedExecutionBackend::Container {
                image,
                engine,
                lifecycle,
                ..
            } => {
                let target = match lifecycle {
                    Lifecycle::Persistent => {
                        execution_target(contract, contract_path, backend, Some(lifecycle))
                    }
                    Lifecycle::Ephemeral => ephemeral_container_target(contract, contract_path),
                };
                let target_strategy = match lifecycle {
                    Lifecycle::Persistent => String::from("persistent container"),
                    Lifecycle::Ephemeral => String::from("ephemeral per-run container"),
                };
                (
                    Some(planned_container_image.unwrap_or(image)),
                    Some(engine),
                    effective
                        .container
                        .map(|container| container_engine_candidates_from_backend(Some(container)))
                        .unwrap_or_else(|| container_engine_candidates(contract)),
                    None,
                    target,
                    target_strategy,
                    None,
                )
            }
            ResolvedExecutionBackend::Remote {
                shared_local_backend: _,
                provider,
                target,
                cwd,
                ..
            } => (
                None,
                None,
                Vec::new(),
                Some(provider),
                Some(target),
                String::from("remote target"),
                cwd,
            ),
            ResolvedExecutionBackend::BackendProvider {
                provider,
                target,
                cwd,
                ..
            } => (
                None,
                None,
                Vec::new(),
                Some(provider),
                Some(target),
                String::from("remote target"),
                cwd,
            ),
        };

    Ok(ExecutionPlanResolved {
        backend: format_backend(backend).to_string(),
        backend_source: backend_source.to_string(),
        lifecycle: resolved_lifecycle.map(format_lifecycle).map(str::to_string),
        lifecycle_source,
        image,
        engine,
        engine_candidates,
        provider,
        target,
        target_strategy,
        cwd,
    })
}

fn resolve_execution_plan_container_image(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    context_name: Option<&str>,
    lifecycle: Option<Lifecycle>,
    fallback_image: Option<&str>,
) -> Result<Option<String>, RunError> {
    let Some(fallback_image) = fallback_image else {
        return Ok(None);
    };
    let Some(context_name) = context_name else {
        return Ok(Some(fallback_image.to_string()));
    };
    let Some(execution) = contract.execution.as_ref() else {
        return Ok(Some(fallback_image.to_string()));
    };

    let matching_backends = execution
        .shared_backends
        .iter()
        .filter(|(binding_name, shared_backend)| {
            if shared_backend.backend != Backend::Container
                || !lifecycle.is_none_or(|selected| shared_backend.lifecycle == selected)
            {
                return false;
            }

            let backend_context_name = shared_backend.context.as_deref().or_else(|| {
                contract.tasks.iter().find_map(|(bound_task_name, task)| {
                    (task.backend_binding_for_backend(Backend::Container)
                        == Some(binding_name.as_str()))
                    .then(|| {
                        selected_task_context_for_backend(
                            contract,
                            bound_task_name,
                            Backend::Container,
                        )
                        .map(|(name, _)| name)
                    })
                    .flatten()
                })
            });

            backend_context_name == Some(context_name)
        })
        .collect::<Vec<(&String, &ExecutionSharedBackend)>>();

    match matching_backends.as_slice() {
        [] => Ok(Some(fallback_image.to_string())),
        [(binding_name, shared_backend)] => {
            let (image, _) = crate::runner::resolve_shared_local_backend_environment(
                Some(contract_path),
                task_name,
                binding_name.as_str(),
                shared_backend.environment.as_ref(),
                fallback_image,
            )?;
            Ok(Some(image))
        }
        _ => Err(RunError::SharedLocalBackendResolutionFailed {
            task: task_name.to_string(),
            binding: String::from("<execution-plan>"),
            details: format!(
                "multiple shared local backends match container context `{context_name}`; add a single deterministic `execution.shared_backends.<name>.context` binding for execution planning"
            ),
        }),
    }
}

struct EnvReport {
    ok: bool,
    summary: EnvSummary,
    sources: Vec<EnvSourceEntry>,
    env: Vec<EnvEntry>,
}

pub fn env(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    task: Option<&str>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure(error.to_string()),
                debug,
                vec![String::from("DEBUG command=env")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=env"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(task) = task {
        debug_lines.push(format!("DEBUG task={task}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "ENV",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota env` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota env", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => match build_env_report(&target.contract, &target.contract_path, task) {
                Ok(report) => match format {
                    OutputFormat::Text => CommandOutput {
                        stdout: render_env_text(&text_path_display, task, &report),
                        stderr: None,
                        exit_code: if report.ok { 0 } else { 1 },
                    },
                    OutputFormat::Json => CommandOutput {
                        stdout: to_json(&EnvSuccess {
                            ok: report.ok,
                            path: &path_display,
                            task,
                            summary: report.summary,
                            sources: report.sources,
                            env: report.env,
                        }),
                        stderr: None,
                        exit_code: if report.ok { 0 } else { 1 },
                    },
                },
                Err(error) => match format {
                    OutputFormat::Text => CommandOutput::failure(error),
                    OutputFormat::Json => CommandOutput::failure(to_json(&EnvFailure {
                        ok: false,
                        path: &path_display,
                        task,
                        error: &error,
                    })),
                },
            },
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "ENV",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota env", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&EnvFailure {
                    ok: false,
                    path: &path_display,
                    task,
                    error: &errors.to_string(),
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "ENV",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota env", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&EnvFailure {
                    ok: false,
                    path: &path_display,
                    task,
                    error: &error.to_string(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

#[derive(Debug, Serialize)]
struct AssistProposalChange<'a> {
    path: &'a str,
    action: &'static str,
    before: YamlValue,
    after: YamlValue,
}

#[derive(Debug, Serialize)]
struct AssistProposalSuccess<'a> {
    ok: bool,
    path: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    member: Option<&'a str>,
    mode: &'static str,
    operation: &'static str,
    subject: BTreeMap<&'static str, &'a str>,
    inputs: BTreeMap<&'static str, String>,
    assumptions: Vec<String>,
    changes: Vec<AssistProposalChange<'a>>,
    diff: String,
    validation: Vec<String>,
    next: String,
}

#[derive(Debug, Serialize)]
struct AssistProposalFailure<'a> {
    ok: bool,
    path: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    member: Option<&'a str>,
    operation: &'static str,
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    subject: BTreeMap<&'static str, &'a str>,
    why: String,
    next: String,
}

enum ResolvedAssistReadinessTarget {
    Task {
        name: String,
        listener: String,
        existing: Option<TaskRuntimeReadinessSpec>,
    },
    Service {
        name: String,
        from: String,
        existing: Option<ServiceReadinessSpec>,
    },
}

pub fn assist_declare_readiness(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    task: Option<&str>,
    service: Option<&str>,
    style: Option<AssistReadinessStyleArg>,
    write: bool,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure(error.to_string()),
                debug,
                vec![String::from("DEBUG command=assist declare-readiness")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=assist declare-readiness"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(task) = task {
        debug_lines.push(format!("DEBUG task={task}"));
    }
    if let Some(service) = service {
        debug_lines.push(format!("DEBUG service={service}"));
    }
    if let Some(style) = style {
        debug_lines.push(format!(
            "DEBUG style={}",
            assist_readiness_style_name(style)
        ));
    }
    if write {
        debug_lines.push(String::from("DEBUG mode=write"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "ASSIST DECLARE-READINESS",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from(
                        "`ota assist declare-readiness` reads repo contracts such as `ota.yaml`",
                    ),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command(
                    "ota assist declare-readiness",
                    &resolved_path,
                ),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => {
                let source_contents = match fs::read_to_string(&target.contract_path) {
                    Ok(contents) => contents,
                    Err(error) => {
                        let error = format!(
                            "failed to read `{}`: {}",
                            compact_contract_path(&target.contract_path),
                            error
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(error),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: assist_subject_map(task, service),
                                    why: error,
                                    next: String::from(
                                        "repair the contract path, then rerun the assist command",
                                    ),
                                }))
                            }
                        };
                    }
                };
                let mut document: YamlValue = match serde_yaml::from_str(&source_contents) {
                    Ok(document) => document,
                    Err(error) => {
                        let why = format!(
                            "failed to parse `{}` for assist preview: {}",
                            compact_contract_path(&target.contract_path),
                            error
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(why.clone()),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: assist_subject_map(task, service),
                                    why,
                                    next: String::from(
                                        "repair the existing contract, then rerun the assist command",
                                    ),
                                }))
                            }
                        };
                    }
                };

                let proposal =
                    match build_assist_readiness_proposal(&target.contract, task, service, style) {
                        Ok(proposal) => proposal,
                        Err((why, next)) => {
                            return match format {
                                OutputFormat::Text => CommandOutput::failure(format!(
                                    "{}\n{} {}\n{} {}",
                                    format_command_header(
                                        "ASSIST DECLARE-READINESS",
                                        &text_path_display
                                    ),
                                    error_key("Why:"),
                                    why,
                                    paint_key("Next:"),
                                    next
                                )),
                                OutputFormat::Json => {
                                    CommandOutput::failure(to_json(&AssistProposalFailure {
                                        ok: false,
                                        path: &path_display,
                                        member,
                                        operation: "declare-readiness",
                                        subject: assist_subject_map(task, service),
                                        why,
                                        next,
                                    }))
                                }
                            };
                        }
                    };

                let after_value = proposal.after_value.clone();
                set_yaml_path(
                    &mut document,
                    &proposal
                        .yaml_path
                        .iter()
                        .map(String::as_str)
                        .collect::<Vec<_>>(),
                    after_value.clone(),
                );
                let yaml = match serde_yaml::to_string(&document) {
                    Ok(yaml) => yaml,
                    Err(error) => {
                        let error = format!(
                            "failed to serialize assist proposal for `{}`: {}",
                            compact_contract_path(&target.contract_path),
                            error
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(error.clone()),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: proposal.subject_json(),
                                    why: error,
                                    next: String::from(
                                        "rerun the assist command after fixing the repo contract",
                                    ),
                                }))
                            }
                        };
                    }
                };

                if let Err(error) = validate_assist_contract_update(
                    &resolved_path,
                    member,
                    &target.contract_path,
                    &yaml,
                ) {
                    return match format {
                        OutputFormat::Text => CommandOutput::failure(error.clone()),
                        OutputFormat::Json => {
                            CommandOutput::failure(to_json(&AssistProposalFailure {
                                ok: false,
                                path: &path_display,
                                member,
                                operation: "declare-readiness",
                                subject: proposal.subject_json(),
                                why: error,
                                next: String::from(
                                    "adjust the selector or style, then rerun the assist command",
                                ),
                            }))
                        }
                    };
                }

                let validation =
                    assist_validation_commands(&resolved_path, &target.contract_path, member);

                if write {
                    match fs::write(&target.contract_path, yaml) {
                        Ok(()) => match format {
                            OutputFormat::Text => {
                                CommandOutput::success(render_assist_readiness_text(
                                    &text_path_display,
                                    &proposal,
                                    "write",
                                    &validation,
                                    None,
                                ))
                            }
                            OutputFormat::Json => {
                                CommandOutput::success(to_json(&AssistProposalSuccess {
                                    ok: true,
                                    path: &path_display,
                                    member,
                                    mode: "write",
                                    operation: "declare-readiness",
                                    subject: proposal.subject_json(),
                                    inputs: proposal.inputs_json(),
                                    assumptions: proposal.assumptions.clone(),
                                    changes: vec![AssistProposalChange {
                                        path: &proposal.change_path,
                                        action: "set",
                                        before: proposal.before_value.clone(),
                                        after: after_value,
                                    }],
                                    diff: proposal.diff(),
                                    validation,
                                    next: String::from(
                                        "rerun `ota doctor` to inspect the updated readiness contract",
                                    ),
                                }))
                            }
                        },
                        Err(error) => {
                            let error = format!(
                                "failed to write `{}`: {}",
                                compact_contract_path(&target.contract_path),
                                error
                            );
                            match format {
                                OutputFormat::Text => CommandOutput::failure(error.clone()),
                                OutputFormat::Json => {
                                    CommandOutput::failure(to_json(&AssistProposalFailure {
                                        ok: false,
                                        path: &path_display,
                                        member,
                                        operation: "declare-readiness",
                                        subject: proposal.subject_json(),
                                        why: error,
                                        next: String::from(
                                            "repair the contract path or permissions, then rerun with `--write`",
                                        ),
                                    }))
                                }
                            }
                        }
                    }
                } else {
                    let preview_target_path = if member.is_some() {
                        &resolved_path
                    } else {
                        &target.contract_path
                    };
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_assist_readiness_text(
                            &text_path_display,
                            &proposal,
                            "preview",
                            &validation,
                            Some(&proposal.preview_next_command(member, preview_target_path)),
                        )),
                        OutputFormat::Json => {
                            CommandOutput::success(to_json(&AssistProposalSuccess {
                                ok: true,
                                path: &path_display,
                                member,
                                mode: "preview",
                                operation: "declare-readiness",
                                subject: proposal.subject_json(),
                                inputs: proposal.inputs_json(),
                                assumptions: proposal.assumptions.clone(),
                                changes: vec![AssistProposalChange {
                                    path: &proposal.change_path,
                                    action: "set",
                                    before: proposal.before_value.clone(),
                                    after: after_value,
                                }],
                                diff: proposal.diff(),
                                validation,
                                next: proposal.preview_next_command(member, preview_target_path),
                            }))
                        }
                    }
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "ASSIST DECLARE-READINESS",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota assist declare-readiness",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&AssistProposalFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    operation: "declare-readiness",
                    subject: assist_subject_map(task, service),
                    why: errors.to_string(),
                    next: String::from(
                        "repair the existing contract, then rerun the assist command",
                    ),
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "ASSIST DECLARE-READINESS",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota assist declare-readiness",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&AssistProposalFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    operation: "declare-readiness",
                    subject: assist_subject_map(task, service),
                    why: error.to_string(),
                    next: String::from("repair the contract path, then rerun the assist command"),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

struct AssistReadinessProposal {
    subject_kind: &'static str,
    subject_name: String,
    style: AssistReadinessStyleArg,
    assumptions: Vec<String>,
    change_path: String,
    yaml_path: Vec<String>,
    before_value: YamlValue,
    after_value: YamlValue,
}

impl AssistReadinessProposal {
    fn subject_json(&self) -> BTreeMap<&'static str, &str> {
        let mut subject = BTreeMap::new();
        subject.insert(self.subject_kind, self.subject_name.as_str());
        subject
    }

    fn inputs_json(&self) -> BTreeMap<&'static str, String> {
        let mut inputs = BTreeMap::new();
        inputs.insert("style", assist_readiness_style_name(self.style).to_string());
        inputs
    }

    fn diff(&self) -> String {
        format!(
            "{}\n- {}\n+ {}",
            self.change_path,
            compact_yaml_inline(&self.before_value),
            compact_yaml_inline(&self.after_value)
        )
    }

    fn preview_next_command(&self, member: Option<&str>, contract_path: &Path) -> String {
        let mut command = String::from("ota assist declare-readiness");
        if let Some(member) = member {
            command.push_str(&format!(" --member {member}"));
        }
        command.push_str(&format!(" --{} {}", self.subject_kind, self.subject_name));
        command.push_str(&format!(
            " --style {} --write",
            assist_readiness_style_name(self.style)
        ));
        let command = command_for_repo_from_contract_path(&command, contract_path);
        format!("rerun with `{command}` to apply this readiness change")
    }
}

fn is_http_readiness_style(style: AssistReadinessStyleArg) -> bool {
    matches!(
        style,
        AssistReadinessStyleArg::SpringHttp | AssistReadinessStyleArg::Http
    )
}

fn assist_subject_map<'a>(
    task: Option<&'a str>,
    service: Option<&'a str>,
) -> BTreeMap<&'static str, &'a str> {
    let mut subject = BTreeMap::new();
    if let Some(task) = task {
        subject.insert("task", task);
    }
    if let Some(service) = service {
        subject.insert("service", service);
    }
    subject
}

fn assist_readiness_style_name(style: AssistReadinessStyleArg) -> &'static str {
    match style {
        AssistReadinessStyleArg::SpringHttp => "spring-http",
        AssistReadinessStyleArg::Http => "http",
        AssistReadinessStyleArg::Tcp => "tcp",
    }
}

fn render_assist_readiness_text(
    path: &str,
    proposal: &AssistReadinessProposal,
    mode: &str,
    validation: &[String],
    preview_next: Option<&str>,
) -> String {
    let mut output = format_command_header("ASSIST DECLARE-READINESS", path);
    output.push_str(&format!("\n\n{} {}", mode_icon(), paint_key("Mode:")));
    output.push_str(&format!(
        " {}",
        if mode == "write" { "write" } else { "preview" }
    ));
    output.push_str(&format!(
        "\n{} {} {}",
        info_bullet(),
        paint_key("Subject:"),
        paint_named_drift_label(
            if proposal.subject_kind == "service" {
                "Service"
            } else {
                "Task"
            },
            &proposal.subject_name,
        )
    ));
    output.push_str(&format!(
        "\n{} {} {}",
        info_bullet(),
        paint_key("Style:"),
        assist_readiness_style_name(proposal.style)
    ));
    output.push_str(&format!("\n\n{}:", paint_section_title("Assumptions")));
    for assumption in &proposal.assumptions {
        output.push_str(&format!("\n{} {}", info_bullet(), assumption));
    }
    if !proposal.before_value.is_null() {
        output.push_str(&format!(
            "\n\n{}:",
            paint_section_title("Current readiness")
        ));
        output.push_str(&format!(
            "\n{} {}",
            info_bullet(),
            paint_backticked_code(&proposal.change_path)
        ));
        let before_yaml =
            serde_yaml::to_string(&proposal.before_value).unwrap_or_else(|_| String::from("---\n"));
        output.push_str(&format!(
            "\n{}",
            stylize_yaml_preview(before_yaml.trim_end())
        ));
    }
    output.push_str(&format!(
        "\n\n{}:",
        paint_section_title("Proposed readiness")
    ));
    output.push_str(&format!(
        "\n{} {}",
        info_bullet(),
        paint_backticked_code(&proposal.change_path)
    ));
    let after_yaml =
        serde_yaml::to_string(&proposal.after_value).unwrap_or_else(|_| String::from("---\n"));
    output.push_str(&format!(
        "\n{}",
        stylize_yaml_preview(after_yaml.trim_end())
    ));
    output.push_str(&format_next_timeline(
        &validation
            .iter()
            .map(|command| format!("run `{}`", command))
            .collect::<Vec<_>>(),
    ));
    if mode == "preview" {
        if let Some(preview_next) = preview_next {
            output.push_str(&format!("\n{} {}", paint_key("Next:"), preview_next));
        }
    } else {
        output.push_str(&format!(
            "\n{} {}",
            paint_key("Result:"),
            format!("applied {}", paint_backticked_code(&proposal.change_path))
        ));
    }
    output
}

fn build_assist_readiness_proposal(
    contract: &Contract,
    task: Option<&str>,
    service: Option<&str>,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<AssistReadinessProposal, (String, String)> {
    match (task, service) {
        (Some(_), Some(_)) => {
            return Err((
                String::from("select either `--task` or `--service`, not both"),
                String::from(
                    "rerun `ota assist declare-readiness` with exactly one target selector",
                ),
            ));
        }
        (None, None) => {
            return Err((
                String::from("one target selector is required"),
                String::from("rerun with `--task <name>` or `--service <name>`"),
            ));
        }
        _ => {}
    }

    match resolve_assist_readiness_target(contract, task, service, requested_style) {
        Ok(ResolvedAssistReadinessTarget::Task {
            name,
            listener,
            existing,
        }) => {
            let style = resolve_assist_style_for_task(contract, &name, &listener, requested_style)?;
            let after = match style {
                AssistReadinessStyleArg::SpringHttp => TaskRuntimeReadinessSpec {
                    kind: TaskRuntimeReadinessKind::Http,
                    listener: Some(listener.clone()),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/actuator/health")),
                    headers: BTreeMap::from([(
                        String::from("Accept"),
                        String::from("application/json"),
                    )]),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: Some(TaskRuntimeReadinessHttpBodySpec {
                        contains: String::from("\"status\":\"UP\""),
                    }),
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Http => TaskRuntimeReadinessSpec {
                    kind: TaskRuntimeReadinessKind::Http,
                    listener: Some(listener.clone()),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/health")),
                    headers: BTreeMap::new(),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Tcp => TaskRuntimeReadinessSpec {
                    kind: TaskRuntimeReadinessKind::Tcp,
                    listener: Some(listener.clone()),
                    method: None,
                    path: None,
                    headers: BTreeMap::new(),
                    success: None,
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
            };
            let before_value = existing
                .as_ref()
                .map(serde_yaml::to_value)
                .transpose()
                .map_err(|error| {
                    (
                        format!("failed to capture existing readiness for preview: {error}"),
                        String::from("rerun the assist command after repairing the contract"),
                    )
                })?
                .unwrap_or(YamlValue::Null);
            let after_value = serde_yaml::to_value(&after).map_err(|error| {
                (
                    format!("failed to build readiness proposal: {error}"),
                    String::from("rerun the assist command after repairing the contract"),
                )
            })?;
            Ok(AssistReadinessProposal {
                subject_kind: "task",
                subject_name: name.clone(),
                style,
                assumptions: vec![
                    format!("task `{name}` already declares a service runtime"),
                    format!("listener `{listener}` is the readiness surface"),
                ],
                change_path: format!("tasks.{name}.runtime.readiness"),
                yaml_path: vec![
                    String::from("tasks"),
                    name,
                    String::from("runtime"),
                    String::from("readiness"),
                ],
                before_value,
                after_value,
            })
        }
        Ok(ResolvedAssistReadinessTarget::Service {
            name,
            from,
            existing,
        }) => {
            let style = resolve_assist_style_for_service(existing.as_ref(), requested_style)?;
            let after = match style {
                AssistReadinessStyleArg::SpringHttp => ServiceReadinessSpec {
                    from: Some(from.clone()),
                    run: None,
                    kind: Some(TaskRuntimeReadinessKind::Http),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/actuator/health")),
                    headers: BTreeMap::from([(
                        String::from("Accept"),
                        String::from("application/json"),
                    )]),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: Some(TaskRuntimeReadinessHttpBodySpec {
                        contains: String::from("\"status\":\"UP\""),
                    }),
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Http => ServiceReadinessSpec {
                    from: Some(from.clone()),
                    run: None,
                    kind: Some(TaskRuntimeReadinessKind::Http),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/health")),
                    headers: BTreeMap::new(),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Tcp => ServiceReadinessSpec {
                    from: Some(from.clone()),
                    run: None,
                    kind: Some(TaskRuntimeReadinessKind::Tcp),
                    method: None,
                    path: None,
                    headers: BTreeMap::new(),
                    success: None,
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
            };
            let before_value = existing
                .as_ref()
                .map(serde_yaml::to_value)
                .transpose()
                .map_err(|error| {
                    (
                        format!(
                            "failed to capture existing service readiness for preview: {error}"
                        ),
                        String::from("rerun the assist command after repairing the contract"),
                    )
                })?
                .unwrap_or(YamlValue::Null);
            let after_value = serde_yaml::to_value(&after).map_err(|error| {
                (
                    format!("failed to build service readiness proposal: {error}"),
                    String::from("rerun the assist command after repairing the contract"),
                )
            })?;
            Ok(AssistReadinessProposal {
                subject_kind: "service",
                subject_name: name.clone(),
                style,
                assumptions: vec![
                    format!("service `{name}` already declares endpoint `{from}`"),
                    format!("structured readiness should anchor to endpoint `{from}`"),
                ],
                change_path: format!("services.{name}.readiness"),
                yaml_path: vec![String::from("services"), name, String::from("readiness")],
                before_value,
                after_value,
            })
        }
        Err(error) => Err(error),
    }
}

fn resolve_assist_style_for_task(
    contract: &Contract,
    task: &str,
    listener_name: &str,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<AssistReadinessStyleArg, (String, String)> {
    let runtime = contract
        .tasks
        .get(task)
        .and_then(|task| task.runtime.as_ref())
        .ok_or_else(|| {
            (
                format!("task `{task}` does not declare a runtime service"),
                String::from(
                    "declare `tasks.<name>.runtime` first, then rerun this assist command",
                ),
            )
        })?;

    let listener = runtime.listeners.get(listener_name).ok_or_else(|| {
        (
            format!(
                "task `{task}` readiness target `{listener_name}` is no longer a declared listener"
            ),
            String::from("repair the runtime listener declaration, then rerun this assist command"),
        )
    })?;
    let inferred = match listener.protocol {
        TaskRuntimeProtocol::Tcp => AssistReadinessStyleArg::Tcp,
        TaskRuntimeProtocol::Http | TaskRuntimeProtocol::Https => AssistReadinessStyleArg::Http,
    };

    if let Some(style) = requested_style {
        let requested_http = is_http_readiness_style(style);
        let listener_http = is_http_readiness_style(inferred);
        if requested_http != listener_http {
            return Err((
                format!(
                    "task `{task}` readiness listener `{listener_name}` uses `protocol: {}`, so `--style {}` does not fit that listener",
                    match listener.protocol {
                        TaskRuntimeProtocol::Http => "http",
                        TaskRuntimeProtocol::Https => "https",
                        TaskRuntimeProtocol::Tcp => "tcp",
                    },
                    assist_readiness_style_name(style)
                ),
                String::from(
                    "rerun with a style that matches the selected listener protocol, or change `runtime.readiness.listener` first",
                ),
            ));
        }
        return Ok(style);
    }

    Ok(inferred)
}

fn resolve_assist_style_for_service(
    existing: Option<&ServiceReadinessSpec>,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<AssistReadinessStyleArg, (String, String)> {
    if let Some(style) = requested_style {
        return Ok(style);
    }

    match existing.and_then(ServiceReadinessSpec::structured_kind) {
        Some(TaskRuntimeReadinessKind::Tcp) => Ok(AssistReadinessStyleArg::Tcp),
        Some(TaskRuntimeReadinessKind::Http) => Ok(AssistReadinessStyleArg::Http),
        None => Err((
            String::from(
                "managed service readiness style is ambiguous without an explicit `--style`",
            ),
            String::from(
                "rerun with `--style tcp` for raw port checks or `--style http` / `spring-http` for HTTP health endpoints",
            ),
        )),
    }
}

fn resolve_assist_readiness_target(
    contract: &Contract,
    task: Option<&str>,
    service: Option<&str>,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<ResolvedAssistReadinessTarget, (String, String)> {
    if let Some(task) = task {
        let task_spec = contract.tasks.get(task).ok_or_else(|| {
            (
                format!("unknown task `{task}`"),
                String::from("run `ota tasks --use` to inspect runnable task usage"),
            )
        })?;
        let runtime = task_spec.runtime.as_ref().ok_or_else(|| {
            (
                format!("task `{task}` does not declare `runtime`"),
                String::from(
                    "declare a task runtime service first, then rerun this assist command",
                ),
            )
        })?;
        let listener = select_assist_task_listener(task, runtime, requested_style)?;
        return Ok(ResolvedAssistReadinessTarget::Task {
            name: task.to_string(),
            listener,
            existing: runtime.readiness.clone(),
        });
    }

    let service = service.expect("service target required when task is absent");
    let spec = contract.services.get(service).ok_or_else(|| {
        (
            format!("unknown service `{service}`"),
            String::from("run `ota services` to inspect declared managed services"),
        )
    })?;
    let from = if let Some(existing) = spec
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.from.clone())
    {
        existing
    } else if spec.endpoints.contains_key("host") {
        String::from("host")
    } else if spec.endpoints.len() == 1 {
        spec.endpoints
            .keys()
            .next()
            .cloned()
            .expect("single endpoint")
    } else {
        return Err((
            format!(
                "service `{service}` has multiple endpoints; assist cannot pick readiness.from safely"
            ),
            String::from(
                "declare `readiness.from` manually or reduce the endpoint choice before rerunning",
            ),
        ));
    };
    Ok(ResolvedAssistReadinessTarget::Service {
        name: service.to_string(),
        from,
        existing: spec.readiness.clone(),
    })
}

fn select_assist_task_listener(
    task: &str,
    runtime: &crate::schema::TaskRuntimeSpec,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<String, (String, String)> {
    if let Some(existing) = runtime
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.listener.clone())
    {
        return Ok(existing);
    }

    let desired_http = matches!(
        requested_style,
        Some(AssistReadinessStyleArg::SpringHttp | AssistReadinessStyleArg::Http)
    );
    let desired_tcp = matches!(requested_style, Some(AssistReadinessStyleArg::Tcp));

    if let Some(listener) = runtime.listeners.get("http") {
        if !desired_tcp
            && matches!(
                listener.protocol,
                TaskRuntimeProtocol::Http | TaskRuntimeProtocol::Https
            )
        {
            return Ok(String::from("http"));
        }
    }

    let matching = runtime
        .listeners
        .iter()
        .filter(|(_, listener)| {
            if desired_http {
                matches!(
                    listener.protocol,
                    TaskRuntimeProtocol::Http | TaskRuntimeProtocol::Https
                )
            } else if desired_tcp {
                matches!(listener.protocol, TaskRuntimeProtocol::Tcp)
            } else {
                true
            }
        })
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();

    if matching.len() == 1 {
        return Ok(matching[0].clone());
    }

    Err((
        format!("task `{task}` does not expose one unambiguous listener for readiness declaration"),
        String::from(
            "declare `runtime.readiness.listener` manually or rerun with a narrower style",
        ),
    ))
}

fn compact_yaml_inline(value: &YamlValue) -> String {
    if value.is_null() {
        return String::from("<absent>");
    }

    serde_yaml::to_string(value)
        .unwrap_or_else(|_| String::from("<unavailable>"))
        .trim()
        .replace('\n', " ")
}

fn set_yaml_path(document: &mut YamlValue, path: &[&str], value: YamlValue) {
    debug_assert!(!path.is_empty());
    let mut current = document;
    for segment in &path[..path.len() - 1] {
        if !matches!(current, YamlValue::Mapping(_)) {
            *current = YamlValue::Mapping(Mapping::new());
        }
        let mapping = current.as_mapping_mut().expect("mapping");
        current = mapping
            .entry(YamlValue::String((*segment).to_string()))
            .or_insert_with(|| YamlValue::Mapping(Mapping::new()));
    }
    if !matches!(current, YamlValue::Mapping(_)) {
        *current = YamlValue::Mapping(Mapping::new());
    }
    current
        .as_mapping_mut()
        .expect("mapping")
        .insert(YamlValue::String(path[path.len() - 1].to_string()), value);
}

fn validate_assist_contract_update(
    resolved_path: &Path,
    member: Option<&str>,
    target_contract_path: &Path,
    yaml: &str,
) -> Result<(), String> {
    match member {
        Some(member) => load_contract_for_member_with_contents(resolved_path, member, Some(yaml))
            .map(|(contract, _)| contract)
            .map_err(|error| error.to_string())
            .and_then(|contract| {
                validate_contract_with_path(&contract, Some(target_contract_path))
                    .map_err(|error| error.to_string())
            }),
        None => parse_contract_str(target_contract_path, yaml)
            .map_err(|error| error.to_string())
            .and_then(|contract| {
                validate_contract_with_path(&contract, Some(target_contract_path))
                    .map_err(|error| error.to_string())
            }),
    }
}

fn assist_validation_commands(
    resolved_path: &Path,
    target_contract_path: &Path,
    member: Option<&str>,
) -> Vec<String> {
    match member {
        Some(member) => [
            command_for_repo_from_contract_path(
                &format!("ota validate --member {member}"),
                resolved_path,
            ),
            command_for_repo_from_contract_path(
                &format!("ota doctor --member {member}"),
                resolved_path,
            ),
        ]
        .into_iter()
        .collect(),
        None => vec![
            command_for_repo_contract_target("ota validate", target_contract_path),
            command_for_repo_contract_target("ota doctor", target_contract_path),
        ],
    }
}

fn build_env_report(
    contract: &Contract,
    contract_path: &Path,
    task_name: Option<&str>,
) -> Result<EnvReport, String> {
    let (task_env, explicit_task_env) = match task_name {
        Some(task_name) => {
            let Some(task) = contract.tasks.get(task_name) else {
                return Err(RunError::UnknownTask {
                    task: task_name.to_string(),
                }
                .to_string());
            };
            (
                effective_task_env_for_selection(
                    contract,
                    task_name,
                    ExecutionOverrides::default(),
                    contract_working_dir(contract_path),
                ),
                Some(&task.env),
            )
        }
        None => (None, None),
    };

    let policy_env = load_policy_env_overlay(contract_path).map_err(|error| error.to_string())?;
    let declared_sources = load_declared_env_sources(contract, contract_path);
    let mut env = Vec::new();
    let mut sources = Vec::new();
    let mut contract_resolved_count = 0usize;
    let mut missing_count = 0usize;
    let mut invalid_count = 0usize;
    let mut source_issue_count = 0usize;

    for source in &declared_sources {
        let status = env_source_status_from_declared(source.status);
        let detail = source.details.clone().or_else(|| match source.status {
            DeclaredEnvSourceStatus::MissingRequired => {
                Some(String::from("declared source missing"))
            }
            _ => None,
        });
        let next = env_source_next_step(source, task_name);
        let issue_count = usize::from(env_source_status_counts_as_issue(status));
        source_issue_count += issue_count;
        sources.push(EnvSourceEntry {
            kind: source.kind.to_string(),
            path: source.path.clone(),
            label: source.label(),
            must_exist: source.must_exist,
            status,
            detail,
            next,
        });
    }

    for (name, requirement) in &contract.env {
        let task_override = task_env.as_ref().and_then(|task_env| task_env.get(name));

        if let Some(value) = task_override {
            let source = if explicit_task_env.is_some_and(|task_env| task_env.contains_key(name)) {
                "task"
            } else {
                "execution"
            };
            env.push(build_task_overridden_env_entry(
                name,
                requirement,
                value,
                source,
            ));
            contract_resolved_count += 1;
            continue;
        }

        let mut resolved = policy_env
            .values
            .get(name)
            .cloned()
            .map(|value| (policy_env.label.clone(), value))
            .or_else(|| {
                std::env::var(name)
                    .ok()
                    .map(|value| (String::from("process"), value))
            })
            .or_else(|| {
                resolve_declared_env_source_value(name, &declared_sources)
                    .map(|(value, source)| (env_resolution_source_label(&source), value))
            })
            .or_else(|| {
                requirement
                    .default
                    .clone()
                    .map(|value| (String::from("default"), value))
            });

        match resolved.as_mut() {
            Some((source, value)) => {
                if name == "PATH" {
                    *value = compose_env_path_value(name, value.as_str(), requirement)?;
                }

                if !requirement.allowed.is_empty()
                    && !requirement.allowed.iter().any(|allowed| allowed == value)
                {
                    invalid_count += 1;
                    let (source_kind, source_path, source_status, source_label) =
                        env_entry_source_metadata(source.as_str(), &declared_sources);
                    env.push(EnvEntry {
                        name: name.clone(),
                        kind: EnvEntryKind::Contract,
                        required: requirement.required,
                        default: requirement.default.clone(),
                        allowed: requirement.allowed.clone(),
                        value: Some(display_env_value(value.as_str(), requirement.secret)),
                        source: source.clone(),
                        source_kind,
                        source_path,
                        source_status,
                        source_label,
                        status: EnvEntryStatus::Invalid,
                        next: Some(env_next_for_invalid(name, &requirement.allowed)),
                    });
                } else {
                    contract_resolved_count += 1;
                    let (source_kind, source_path, source_status, source_label) =
                        env_entry_source_metadata(source.as_str(), &declared_sources);
                    env.push(EnvEntry {
                        name: name.clone(),
                        kind: EnvEntryKind::Contract,
                        required: requirement.required,
                        default: requirement.default.clone(),
                        allowed: requirement.allowed.clone(),
                        value: Some(display_env_value(value.as_str(), requirement.secret)),
                        source: source.clone(),
                        source_kind,
                        source_path,
                        source_status,
                        source_label,
                        status: EnvEntryStatus::Resolved,
                        next: None,
                    });
                }
            }
            None if requirement.required => {
                missing_count += 1;
                env.push(EnvEntry {
                    name: name.clone(),
                    kind: EnvEntryKind::Contract,
                    required: true,
                    default: requirement.default.clone(),
                    allowed: requirement.allowed.clone(),
                    value: None,
                    source: String::from("missing"),
                    source_kind: None,
                    source_path: None,
                    source_status: None,
                    source_label: None,
                    status: EnvEntryStatus::Missing,
                    next: Some(env_next_for_missing(name, task_name)),
                });
            }
            None => {
                env.push(EnvEntry {
                    name: name.clone(),
                    kind: EnvEntryKind::Contract,
                    required: false,
                    default: requirement.default.clone(),
                    allowed: requirement.allowed.clone(),
                    value: None,
                    source: String::from("missing"),
                    source_kind: None,
                    source_path: None,
                    source_status: None,
                    source_label: None,
                    status: EnvEntryStatus::Optional,
                    next: None,
                });
            }
        }
    }

    if let Some(task_env) = task_env.as_ref() {
        for (name, value) in task_env {
            if contract.env.contains_key(name) {
                continue;
            }
            let source = if explicit_task_env.is_some_and(|raw_env| raw_env.contains_key(name)) {
                String::from("task")
            } else {
                String::from("execution")
            };
            env.push(EnvEntry {
                name: name.clone(),
                kind: EnvEntryKind::Task,
                required: false,
                default: None,
                allowed: Vec::new(),
                value: Some(value.clone()),
                source,
                source_kind: None,
                source_path: None,
                source_status: None,
                source_label: None,
                status: EnvEntryStatus::Task,
                next: None,
            });
        }
    }

    let task_count = env
        .iter()
        .filter(|entry| matches!(entry.kind, EnvEntryKind::Task))
        .count();

    Ok(EnvReport {
        ok: missing_count == 0 && invalid_count == 0 && source_issue_count == 0,
        summary: EnvSummary {
            contract_count: contract.env.len(),
            source_count: declared_sources.len(),
            source_issue_count,
            task_count,
            resolved_count: contract_resolved_count,
            missing_count,
            invalid_count,
        },
        sources,
        env,
    })
}

fn env_source_status_from_declared(status: DeclaredEnvSourceStatus) -> EnvSourceStatus {
    match status {
        DeclaredEnvSourceStatus::Loaded => EnvSourceStatus::Loaded,
        DeclaredEnvSourceStatus::MissingOptional => EnvSourceStatus::MissingOptional,
        DeclaredEnvSourceStatus::MissingRequired => EnvSourceStatus::MissingRequired,
        DeclaredEnvSourceStatus::ParseFailed => EnvSourceStatus::ParseFailed,
        DeclaredEnvSourceStatus::InvalidStructure => EnvSourceStatus::InvalidStructure,
        DeclaredEnvSourceStatus::Collision => EnvSourceStatus::Collision,
    }
}

fn env_source_status_counts_as_issue(status: EnvSourceStatus) -> bool {
    !matches!(
        status,
        EnvSourceStatus::Loaded | EnvSourceStatus::MissingOptional
    )
}

fn env_source_next_step(
    source: &LoadedDeclaredEnvSource,
    task_name: Option<&str>,
) -> Option<String> {
    match source.status {
        DeclaredEnvSourceStatus::Loaded | DeclaredEnvSourceStatus::MissingOptional => None,
        DeclaredEnvSourceStatus::MissingRequired => Some(format!(
            "create `{}` or remove `must_exist: true`, then rerun {}",
            source.path,
            env_rerun_command(task_name)
        )),
        DeclaredEnvSourceStatus::ParseFailed
        | DeclaredEnvSourceStatus::InvalidStructure
        | DeclaredEnvSourceStatus::Collision => Some(format!(
            "fix `{}` so ota can load declared source `{}`, then rerun {}",
            source.path,
            source.label(),
            env_rerun_command(task_name)
        )),
    }
}

fn env_rerun_command(task_name: Option<&str>) -> String {
    match task_name {
        Some(task_name) => format!("`ota env --task {task_name}`"),
        None => String::from("`ota env`"),
    }
}

fn env_entry_source_metadata(
    source: &str,
    declared_sources: &[LoadedDeclaredEnvSource],
) -> (
    Option<String>,
    Option<String>,
    Option<EnvSourceStatus>,
    Option<String>,
) {
    let Some(declared) = declared_sources
        .iter()
        .find(|candidate| candidate.label() == source)
    else {
        return (None, None, None, None);
    };
    (
        Some(declared.kind.to_string()),
        Some(declared.path.clone()),
        Some(env_source_status_from_declared(declared.status)),
        Some(declared.label()),
    )
}

fn build_task_overridden_env_entry(
    name: &str,
    requirement: &EnvRequirement,
    value: &str,
    source: &str,
) -> EnvEntry {
    EnvEntry {
        name: name.to_string(),
        kind: EnvEntryKind::Contract,
        required: requirement.required,
        default: requirement.default.clone(),
        allowed: requirement.allowed.clone(),
        value: Some(display_env_value(value, requirement.secret)),
        source: String::from(source),
        source_kind: None,
        source_path: None,
        source_status: None,
        source_label: None,
        status: EnvEntryStatus::Resolved,
        next: None,
    }
}

fn display_env_value(value: &str, secret: bool) -> String {
    if secret {
        String::from("<redacted>")
    } else {
        value.to_string()
    }
}

fn env_next_for_missing(name: &str, task_name: Option<&str>) -> String {
    match task_name {
        Some(task_name) => format!(
            "set {name} in policy env, the shell, a declared env source, or task env for `{task_name}`, then rerun `ota env --task {task_name}`"
        ),
        None => format!(
            "set {name} in policy env, the shell, or a declared env source, then rerun `ota env`"
        ),
    }
}

fn env_next_for_invalid(name: &str, allowed: &[String]) -> String {
    format!(
        "set {name} to one of: {}, then rerun `ota env`",
        allowed.join(", ")
    )
}

fn compose_env_path_value(
    name: &str,
    base: &str,
    requirement: &EnvRequirement,
) -> Result<String, String> {
    if requirement.prepend.is_empty() && requirement.append.is_empty() {
        return Ok(base.to_string());
    }

    let mut entries = Vec::with_capacity(1 + requirement.prepend.len() + requirement.append.len());
    entries.extend(requirement.prepend.iter().cloned().map(OsString::from));
    entries.extend(std::env::split_paths(base).map(|path| path.into_os_string()));
    entries.extend(requirement.append.iter().cloned().map(OsString::from));

    std::env::join_paths(entries)
        .map(|joined| joined.to_string_lossy().into_owned())
        .map_err(|source| {
            format!("could not compose environment variable `{name}` as a PATH: {source}")
        })
}

fn render_env_text(path: &str, task: Option<&str>, report: &EnvReport) -> String {
    let mut stdout = format!(
        "{}\n\n{}",
        format_command_header("ENV", path),
        render_readiness_status(report.ok)
    );
    if let Some(task) = task {
        stdout.push_str(&format!("\n\n{} {}", paint("Task:", "1"), task));
    }
    stdout.push_str(&format!("\n\n{}", paint_section_title("Overview")));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Contract env:"),
        report.summary.contract_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Declared sources:"),
        report.summary.source_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Source issues:"),
        report.summary.source_issue_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Task env:"),
        report.summary.task_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Resolved:"),
        report.summary.resolved_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Missing:"),
        report.summary.missing_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Invalid:"),
        report.summary.invalid_count
    ));

    stdout.push_str("\n\n");
    stdout.push_str(&paint_section_title("Contract env"));
    if report.summary.contract_count == 0 {
        stdout.push_str(&format!("\n{} none", info_bullet()));
    } else {
        for entry in report
            .env
            .iter()
            .filter(|entry| matches!(entry.kind, EnvEntryKind::Contract))
        {
            stdout.push_str(&render_env_entry_text(entry));
        }
    }

    if !report.sources.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Declared env sources")
        ));
        for source in &report.sources {
            stdout.push_str(&render_env_source_text(source));
        }
    }

    if task.is_some() && report.summary.task_count > 0 {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Task env")));
        for entry in report
            .env
            .iter()
            .filter(|entry| matches!(entry.kind, EnvEntryKind::Task))
        {
            stdout.push_str(&render_env_entry_text(entry));
        }
    }

    stdout
}

fn render_env_entry_text(entry: &EnvEntry) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&format!("{} {}", list_bullet(), paint(&entry.name, "1")));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Kind:"),
        render_env_kind(entry.kind)
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Required:"),
        if entry.required { "true" } else { "false" }
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Value:"),
        entry.value.as_deref().unwrap_or("-")
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Source:"),
        render_env_entry_provenance(entry)
    ));
    if let Some(source_kind) = entry.source_kind.as_deref() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source Kind:"),
            source_kind
        ));
    }
    if let Some(source_path) = entry.source_path.as_deref() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source Path:"),
            source_path
        ));
    }
    if let Some(source_status) = entry.source_status {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source Status:"),
            render_env_source_status(source_status)
        ));
    }
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Status:"),
        render_env_status(entry.status)
    ));
    if !entry.allowed.is_empty() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Allowed:"),
            entry.allowed.join(", ")
        ));
    }
    if let Some(default) = entry.default.as_deref() {
        output.push_str(&format!("\n  {} {}", paint_key("Default:"), default));
    }
    if let Some(next) = entry.next.as_deref() {
        output.push_str(&format!("\n  {} {}", paint_key("Next:"), next));
    }
    output
}

fn render_env_source_text(source: &EnvSourceEntry) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&format!(
        "{} {}:{}",
        list_bullet(),
        paint(&source.kind, "1"),
        source.path
    ));
    output.push_str(&format!("\n  {} {}", paint_key("Label:"), source.label));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Must Exist:"),
        if source.must_exist { "true" } else { "false" }
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Status:"),
        render_env_source_status(source.status)
    ));
    if let Some(detail) = &source.detail {
        output.push_str(&format!("\n  {} {}", paint_key("Detail:"), detail));
    }
    if let Some(next) = &source.next {
        output.push_str(&format!("\n  {} {}", paint_key("Next:"), next));
    }
    output
}

fn render_env_source_status(status: EnvSourceStatus) -> &'static str {
    match status {
        EnvSourceStatus::Loaded => "loaded",
        EnvSourceStatus::MissingOptional => "missing optional",
        EnvSourceStatus::MissingRequired => "missing required",
        EnvSourceStatus::ParseFailed => "parse failed",
        EnvSourceStatus::InvalidStructure => "invalid structure",
        EnvSourceStatus::Collision => "collision",
    }
}

fn render_env_entry_provenance(entry: &EnvEntry) -> &'static str {
    if entry.source_kind.is_some() {
        "source file"
    } else {
        match entry.source.as_str() {
            "process" => "existing env",
            "default" => "default",
            "task" => "task env",
            "execution" => "execution env",
            "missing" => "missing",
            _ if entry.source.contains("policy") => "policy",
            _ => "other",
        }
    }
}

fn render_env_kind(kind: EnvEntryKind) -> &'static str {
    match kind {
        EnvEntryKind::Contract => "contract",
        EnvEntryKind::Task => "task",
    }
}

fn render_env_status(status: EnvEntryStatus) -> &'static str {
    match status {
        EnvEntryStatus::Resolved => "resolved",
        EnvEntryStatus::Missing => "missing",
        EnvEntryStatus::Optional => "optional",
        EnvEntryStatus::Invalid => "invalid",
        EnvEntryStatus::Task => "task",
    }
}

pub fn diff(base: &Path, target: &Path, format: OutputFormat, debug: bool) -> CommandOutput {
    let base_input = base.display().to_string();
    let target_input = target.display().to_string();

    let base_path = match resolve_diff_contract_path(base) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(error.clone()),
                    OutputFormat::Json => CommandOutput::failure(to_json(&DiffFailure {
                        ok: false,
                        base: &base_input,
                        target: &target_input,
                        error: &error,
                    })),
                },
                debug,
                vec![String::from("DEBUG command=diff")],
            );
        }
    };
    let target_path = match resolve_diff_contract_path(target) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(error.clone()),
                    OutputFormat::Json => CommandOutput::failure(to_json(&DiffFailure {
                        ok: false,
                        base: &base_input,
                        target: &target_input,
                        error: &error,
                    })),
                },
                debug,
                vec![String::from("DEBUG command=diff")],
            );
        }
    };

    let base_display = base_path.display().to_string();
    let target_display = target_path.display().to_string();
    let debug_lines = vec![
        String::from("DEBUG command=diff"),
        format!("DEBUG base_path={base_display}"),
        format!("DEBUG target_path={target_display}"),
    ];

    finalize_debug(
        match (
            load_diff_contract(&base_path),
            load_diff_contract(&target_path),
        ) {
            (Ok(base_contract), Ok(target_contract)) => {
                let changes = collect_diff_changes(&base_contract, &target_contract);
                let summary = summarize_diff_changes(&changes);
                match format {
                    OutputFormat::Text => {
                        let mut stdout = format!(
                            "{}\n\n{}",
                            format_command_header(
                                "DIFF",
                                &format!(
                                    "{} -> {}",
                                    compact_contract_path(&base_path),
                                    compact_contract_path(&target_path)
                                )
                            ),
                            render_diff_status_word(changes.is_empty())
                        );
                        if changes.is_empty() {
                            stdout.push_str("\n\nno semantic differences");
                        } else {
                            render_diff_section(
                                &mut stdout,
                                "Added",
                                changes.iter().filter(|change| change.status == "add"),
                            );
                            render_diff_section(
                                &mut stdout,
                                "Removed",
                                changes.iter().filter(|change| change.status == "remove"),
                            );
                            render_diff_section(
                                &mut stdout,
                                "Changed",
                                changes.iter().filter(|change| change.status == "change"),
                            );
                        }
                        stdout.push_str(&render_diff_summary_text(&summary));
                        CommandOutput {
                            stdout,
                            stderr: None,
                            exit_code: 0,
                        }
                    }
                    OutputFormat::Json => CommandOutput {
                        stdout: to_json(&DiffSuccess {
                            ok: changes.is_empty(),
                            base: &base_display,
                            target: &target_display,
                            summary,
                            changes: &changes,
                        }),
                        stderr: None,
                        exit_code: 0,
                    },
                }
            }
            (Err(error), _) | (_, Err(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(error),
                OutputFormat::Json => CommandOutput::failure(to_json(&DiffFailure {
                    ok: false,
                    base: &base_display,
                    target: &target_display,
                    error: &error,
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn listed_task_summaries<'a>(
    contract: &'a Contract,
    include_internal: bool,
) -> Vec<TaskSummary<'a>> {
    let mut tasks = contract
        .tasks
        .iter()
        .filter(|(_, task)| include_internal || !task.internal)
        .map(|(name, task)| TaskSummary::from_spec(name, task, current_os(), contract))
        .collect::<Vec<_>>();

    if !include_internal {
        let visible_task_names = tasks
            .iter()
            .map(|task| task.name.to_string())
            .collect::<BTreeSet<_>>();
        for task in &mut tasks {
            task.retain_visible_task_relationships(&visible_task_names);
        }
    }

    tasks
}

fn listed_agent_summary<'a>(
    contract: &'a Contract,
    include_internal: bool,
    tasks: &[TaskSummary<'a>],
) -> Option<AgentSummary<'a>> {
    let mut agent = contract
        .agent
        .as_ref()
        .and_then(AgentSummary::from_config)?;
    if !include_internal {
        let visible_task_names = tasks
            .iter()
            .map(|task| task.name.to_string())
            .collect::<BTreeSet<_>>();
        agent.retain_visible_tasks(&visible_task_names);
    }
    (!agent.is_empty()).then_some(agent)
}

pub fn tasks(
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    use_cmd: bool,
    all: bool,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=tasks")],
        );
    }

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure(error.to_string()),
                debug,
                vec![String::from("DEBUG command=tasks")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=tasks"),
        format!("DEBUG contract_path={path_display}"),
    ];
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "TASKS",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota tasks` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota tasks", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, single_member) {
            Ok(target) if members.is_empty() || members.len() == 1 => {
                let task_summaries = listed_task_summaries(&target.contract, all);
                let agent_summary = listed_agent_summary(&target.contract, all, &task_summaries);

                if members.is_empty()
                    && target.contract_path == resolved_path
                    && target.contract.workspace.as_ref().is_some_and(|workspace| {
                        workspace.workspace_type == crate::schema::RepoWorkspaceType::Monorepo
                    })
                {
                    let mut text_sections = vec![render_tasks_output_text(
                        use_cmd,
                        &text_path_display,
                        agent_summary.as_ref(),
                        &task_summaries,
                    )];
                    let mut member_results = Vec::new();

                    if let Some(workspace) = target.contract.workspace.as_ref() {
                        for member in &workspace.members {
                            let member_target =
                                match load_and_validate_target(&resolved_path, Some(member)) {
                                    Ok(target) => target,
                                    Err(ContractProblem::Validation(errors)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(errors.to_string())
                                                }
                                                OutputFormat::Json => {
                                                    CommandOutput::failure(to_json(&TasksFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: errors
                                                            .errors()
                                                            .iter()
                                                            .map(ToString::to_string)
                                                            .collect(),
                                                        error: None,
                                                    }))
                                                }
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                    Err(ContractProblem::Load(error)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(error.to_string())
                                                }
                                                OutputFormat::Json => {
                                                    CommandOutput::failure(to_json(&TasksFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: Vec::new(),
                                                        error: Some(error.to_string()),
                                                    }))
                                                }
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                };
                            let member_tasks = listed_task_summaries(&member_target.contract, all);
                            let member_agent =
                                listed_agent_summary(&member_target.contract, all, &member_tasks);
                            text_sections.push(render_tasks_output_text(
                                use_cmd,
                                &display_contract_target(
                                    &compact_path_display,
                                    Some(member.as_str()),
                                ),
                                member_agent.as_ref(),
                                &member_tasks,
                            ));
                            member_results.push(json!({
                                "member": member,
                                "agent": member_agent,
                                "tasks": member_tasks,
                            }));
                        }
                    }

                    match format {
                        OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                        OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                            "ok": true,
                            "path": path_display,
                            "agent": agent_summary,
                            "members": member_results,
                            "tasks": task_summaries,
                        }))),
                    }
                } else {
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_tasks_output_text(
                            use_cmd,
                            &text_path_display,
                            agent_summary.as_ref(),
                            &task_summaries,
                        )),
                        OutputFormat::Json => CommandOutput::success(to_json(&TasksSuccess {
                            ok: true,
                            path: &path_display,
                            agent: agent_summary,
                            members: Vec::new(),
                            tasks: task_summaries,
                        })),
                    }
                }
            }
            Ok(_) => {
                let mut text_sections = Vec::new();
                let mut member_results = Vec::new();
                for member in members {
                    let target =
                        match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                            Ok(target) => target,
                            Err(ContractProblem::Validation(errors)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(errors.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&TasksFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: errors
                                                    .errors()
                                                    .iter()
                                                    .map(ToString::to_string)
                                                    .collect(),
                                                error: None,
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                            Err(ContractProblem::Load(error)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(error.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&TasksFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: Vec::new(),
                                                error: Some(error.to_string()),
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    let tasks = listed_task_summaries(&target.contract, all);
                    let agent = listed_agent_summary(&target.contract, all, &tasks);
                    text_sections.push(render_tasks_output_text(
                        use_cmd,
                        &display_contract_target(&compact_path_display, Some(member.as_str())),
                        agent.as_ref(),
                        &tasks,
                    ));
                    member_results.push(json!({
                        "member": member,
                        "agent": agent,
                        "tasks": tasks,
                    }));
                }

                match format {
                    OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                    OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                        "ok": true,
                        "path": path_display,
                        "members": member_results,
                        "tasks": Vec::<JsonValue>::new(),
                    }))),
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "TASKS",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota tasks", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&TasksFailure {
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "TASKS",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota tasks", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&TasksFailure {
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn services(
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=services")],
        );
    }

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure(error.to_string()),
                debug,
                vec![String::from("DEBUG command=services")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=services"),
        format!("DEBUG contract_path={path_display}"),
    ];
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "SERVICES",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota services` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota services", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, single_member) {
            Ok(target) if members.is_empty() || members.len() == 1 => {
                let service_summaries = target
                    .contract
                    .services
                    .iter()
                    .map(|(name, service)| ServiceSummary::from_spec(name, service))
                    .collect::<Vec<_>>();

                if members.is_empty()
                    && target.contract_path == resolved_path
                    && target.contract.workspace.as_ref().is_some_and(|workspace| {
                        workspace.workspace_type == crate::schema::RepoWorkspaceType::Monorepo
                    })
                {
                    let mut text_sections = vec![render_services_output_text(
                        &text_path_display,
                        &service_summaries,
                    )];
                    let mut member_results = Vec::new();

                    if let Some(workspace) = target.contract.workspace.as_ref() {
                        for member in &workspace.members {
                            let member_target =
                                match load_and_validate_target(&resolved_path, Some(member)) {
                                    Ok(target) => target,
                                    Err(ContractProblem::Validation(errors)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(errors.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&ServicesFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: errors
                                                            .errors()
                                                            .iter()
                                                            .map(ToString::to_string)
                                                            .collect(),
                                                        error: None,
                                                    }),
                                                ),
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                    Err(ContractProblem::Load(error)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(error.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&ServicesFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: Vec::new(),
                                                        error: Some(error.to_string()),
                                                    }),
                                                ),
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                };
                            let member_services = member_target
                                .contract
                                .services
                                .iter()
                                .map(|(name, service)| ServiceSummary::from_spec(name, service))
                                .collect::<Vec<_>>();
                            text_sections.push(render_services_output_text(
                                &display_contract_target(
                                    &compact_path_display,
                                    Some(member.as_str()),
                                ),
                                &member_services,
                            ));
                            member_results.push(MemberServicesSuccess {
                                member: member.to_string(),
                                services: member_services,
                            });
                        }
                    }

                    match format {
                        OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                        OutputFormat::Json => CommandOutput::success(to_json(&ServicesSuccess {
                            ok: true,
                            path: &path_display,
                            members: member_results,
                            services: service_summaries,
                        })),
                    }
                } else {
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_services_output_text(
                            &text_path_display,
                            &service_summaries,
                        )),
                        OutputFormat::Json => CommandOutput::success(to_json(&ServicesSuccess {
                            ok: true,
                            path: &path_display,
                            members: Vec::new(),
                            services: service_summaries,
                        })),
                    }
                }
            }
            Ok(_) => {
                let mut text_sections = Vec::new();
                let mut member_results = Vec::new();
                for member in members {
                    let target =
                        match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                            Ok(target) => target,
                            Err(ContractProblem::Validation(errors)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(errors.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&ServicesFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: errors
                                                    .errors()
                                                    .iter()
                                                    .map(ToString::to_string)
                                                    .collect(),
                                                error: None,
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                            Err(ContractProblem::Load(error)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(error.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&ServicesFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: Vec::new(),
                                                error: Some(error.to_string()),
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    let services = target
                        .contract
                        .services
                        .iter()
                        .map(|(name, service)| ServiceSummary::from_spec(name, service))
                        .collect::<Vec<_>>();
                    text_sections.push(render_services_output_text(
                        &display_contract_target(&compact_path_display, Some(member.as_str())),
                        &services,
                    ));
                    member_results.push(MemberServicesSuccess {
                        member: member.to_string(),
                        services,
                    });
                }

                match format {
                    OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                    OutputFormat::Json => CommandOutput::success(to_json(&ServicesSuccess {
                        ok: true,
                        path: &path_display,
                        members: member_results,
                        services: Vec::new(),
                    })),
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "SERVICES",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota services", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ServicesFailure {
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "SERVICES",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota services", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ServicesFailure {
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn render_services_output_text(path: &str, services: &[ServiceSummary]) -> String {
    let mut output = format_command_header("SERVICES", path);
    output.push('\n');

    if services.is_empty() {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint("No declared services.", "1")
        ));
        output.push_str(&format_next_timeline(&[
            String::from("run `ota doctor` to inspect readiness without managed services"),
            String::from("add `services` to `ota.yaml` when repo readiness depends on local infra"),
        ]));
        return output;
    }

    for service in services {
        let manager = service
            .manager
            .as_ref()
            .map(|manager| manager.kind.as_str())
            .or(service.provider.as_deref())
            .unwrap_or("-");
        output.push_str(&format!(
            "\n\n{} {} [{}]",
            list_bullet(),
            paint(&service.name, "1"),
            if service.required {
                "required"
            } else {
                "optional"
            }
        ));

        output.push_str(&format!("\n  {} {manager}", paint_key("manager:")));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("depends on:"),
            if service.depends_on.is_empty() {
                String::from("-")
            } else {
                service.depends_on.join(", ")
            }
        ));
        if let Some(readiness) = service.readiness.as_ref() {
            append_wrapped_detail(
                &mut output,
                "readiness:",
                &format_service_readiness_summary(readiness),
                "  ",
                84,
                stylize_inline_text,
            );
        }
        if let Some(healthcheck) = service.healthcheck.as_deref() {
            append_wrapped_detail(
                &mut output,
                "healthcheck:",
                healthcheck,
                "  ",
                84,
                stylize_inline_text,
            );
        }
        if let Some(timeout) = service.timeout {
            output.push_str(&format!("\n  {} {timeout}s", paint_key("timeout:")));
        }

        if !service.endpoints.is_empty() {
            let context_width = service
                .endpoints
                .keys()
                .map(|context| context.len())
                .max()
                .unwrap_or(0);
            output.push_str(&format!("\n  {}", paint_key("endpoints:")));
            for (context, endpoint) in &service.endpoints {
                output.push_str(&format!(
                    "\n    {:<context_width$}  {}:{}",
                    context,
                    endpoint.address,
                    endpoint.port,
                    context_width = context_width
                ));
            }
        }

        if service.start.is_some() || service.stop.is_some() {
            let command_label_width = ["start", "stop"]
                .into_iter()
                .filter(|label| match *label {
                    "start" => service.start.is_some(),
                    "stop" => service.stop.is_some(),
                    _ => false,
                })
                .map(str::len)
                .max()
                .unwrap_or(0);
            output.push_str(&format!("\n  {}", paint_key("commands:")));
            if let Some(start) = service.start.as_deref() {
                output.push_str(&format!(
                    "\n    {} {}",
                    paint_key(&format!("{:<command_label_width$}", "start")),
                    stylize_inline_text(start)
                ));
            }
            if let Some(stop) = service.stop.as_deref() {
                output.push_str(&format!(
                    "\n    {} {}",
                    paint_key(&format!("{:<command_label_width$}", "stop")),
                    stylize_inline_text(stop)
                ));
            }
        }

        output.push_str(&format!(
            "\n  {} {}, {}",
            paint_key("managed by:"),
            paint_code("ota doctor"),
            paint_code("ota up")
        ));
    }

    output
}

fn format_service_readiness_summary(readiness: &ServiceReadinessSummary) -> String {
    let from = readiness.from.as_deref().unwrap_or("?");
    if let Some(run) = readiness.run.as_deref() {
        return format!("from {from} -> {run}");
    }

    let mut detail = String::new();
    if let Some(kind) = readiness.kind.as_deref() {
        detail.push_str(kind);
    }
    if let Some(method) = readiness.method.as_deref() {
        if !detail.is_empty() {
            detail.push(' ');
        }
        detail.push_str(method);
    }
    if let Some(path) = readiness.path.as_deref() {
        if !detail.is_empty() {
            detail.push(' ');
        }
        detail.push_str(path);
    }
    if let Some(success) = readiness.success.as_ref()
        && !success.status.is_empty()
    {
        detail.push_str(" status=");
        detail.push_str(
            &success
                .status
                .iter()
                .map(|status: &u16| status.to_string())
                .collect::<Vec<_>>()
                .join(","),
        );
    }
    if let Some(body) = readiness.body.as_ref() {
        detail.push_str(" contains=");
        detail.push_str(body.contains.as_str());
    }
    if detail.is_empty() {
        detail.push_str("structured probe");
    }
    format!("from {from} -> {detail}")
}

pub fn run_command(
    task_name: &str,
    path: Option<&Path>,
    file_override: Option<&Path>,
    overrides: ExecutionOverrides,
    members: &[String],
    task_inputs: &[String],
    debug: bool,
    show_receipt: bool,
    stream: bool,
    persist_logs: bool,
) -> CommandOutput {
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=run"),
                format!("DEBUG task={task_name}"),
            ],
        );
    }

    let (resolved_path, normalized_task_inputs) = match resolve_repo_run_path_and_inputs(
        task_name,
        path,
        file_override,
        members,
        task_inputs,
    ) {
        Ok(target) => target,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure(stylize_text_failure("ota run", &error.to_string())),
                debug,
                vec![
                    String::from("DEBUG command=run"),
                    format!("DEBUG task={task_name}"),
                ],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let mut debug_lines = vec![
        String::from("DEBUG command=run"),
        format!("DEBUG task={task_name}"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if normalized_task_inputs != task_inputs {
        debug_lines.push(format!(
            "DEBUG task_inputs={}",
            normalized_task_inputs.join(" ")
        ));
    }
    if let Some(backend) = overrides.backend {
        debug_lines.push(format!(
            "DEBUG backend_override={}",
            format_backend(backend)
        ));
    }
    if let Some(lifecycle) = overrides.lifecycle {
        debug_lines.push(format!(
            "DEBUG lifecycle_override={}",
            format_lifecycle(lifecycle)
        ));
    }
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    finalize_debug(
        match run_contract_targets(
            task_name,
            &resolved_path,
            overrides,
            members,
            &normalized_task_inputs,
            show_receipt,
            run_command_streaming_enabled(stream),
            persist_logs,
        ) {
            Ok(stderr) => CommandOutput {
                stdout: String::new(),
                stderr: (!stderr.is_empty()).then_some(stderr),
                exit_code: 0,
            },
            Err(error) => CommandOutput {
                stdout: String::new(),
                stderr: Some(match (error.summary, error.receipt) {
                    (Some(summary), Some(receipt)) if error.message.is_empty() => {
                        format!("{summary}\n{receipt}")
                    }
                    (Some(summary), Some(receipt)) => {
                        format!("{summary}\n\n{}\n{}", error.message, receipt)
                    }
                    (Some(summary), None) if error.message.is_empty() => summary,
                    (Some(summary), None) => format!("{summary}\n\n{}", error.message),
                    (None, Some(receipt)) if error.message.is_empty() => receipt,
                    (None, Some(receipt)) => format!("{}\n{}", error.message, receipt),
                    (None, None) => error.message,
                }),
                exit_code: error.exit_code,
            },
        },
        debug,
        debug_lines,
    )
}

fn resolve_repo_run_path_and_inputs(
    task_name: &str,
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    task_inputs: &[String],
) -> Result<(PathBuf, Vec<String>), ResolveContractError> {
    match resolve_contract_path(path, file_override) {
        Ok(path) => Ok((path, task_inputs.to_vec())),
        Err(error @ ResolveContractError::MissingExplicitPath { .. }) => {
            maybe_reinterpret_missing_repo_run_path(
                task_name,
                path,
                file_override,
                members,
                task_inputs,
            )
            .ok_or(error)
        }
        Err(error) => Err(error),
    }
}

fn maybe_reinterpret_missing_repo_run_path(
    task_name: &str,
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    task_inputs: &[String],
) -> Option<(PathBuf, Vec<String>)> {
    let shorthand_value = path?;
    if !task_inputs.is_empty() || !can_reinterpret_missing_repo_run_path(shorthand_value) {
        return None;
    }

    let resolved_path = resolve_contract_path(None, file_override).ok()?;
    let contract = load_repo_run_shorthand_contract(&resolved_path, members)?;
    let task = contract.tasks.get(task_name)?;
    if task.inputs.len() != 1 {
        return None;
    }

    Some((
        resolved_path,
        vec![shorthand_value.as_os_str().to_string_lossy().to_string()],
    ))
}

fn load_repo_run_shorthand_contract(path: &Path, members: &[String]) -> Option<Contract> {
    match members {
        [] => load_contract(path).ok(),
        [member] => load_contract_for_member(path, member)
            .ok()
            .map(|(contract, _)| contract),
        _ => None,
    }
}

fn can_reinterpret_missing_repo_run_path(path: &Path) -> bool {
    let value = path.as_os_str().to_string_lossy();
    !value.is_empty()
        && !value.starts_with('.')
        && !value.contains('/')
        && !value.contains('\\')
        && !value.ends_with(".yaml")
        && !value.ends_with(".yml")
}

fn run_command_streaming_enabled(force_stream: bool) -> bool {
    force_stream || (!plain_mode() && (io::stdout().is_terminal() || io::stderr().is_terminal()))
}

pub fn self_update(version: Option<&str>, channel: Option<&str>, debug: bool) -> CommandOutput {
    finalize_debug(
        update::self_update(version, channel),
        debug,
        vec![String::from("DEBUG command=self-update")],
    )
}

fn policy_init_target_error(path: &Path) -> String {
    format!(
        "`{}` is not a canonical policy target; pass a repo root, a `.ota` directory, or an explicit `.ota/org-policy.yaml` path",
        compact_path(path, ".")
    )
}

struct PolicyInitTemplate {
    config: JsonValue,
    yaml: &'static str,
}

fn policy_init_template(preset: Option<&str>) -> PolicyInitTemplate {
    match preset {
        Some("required-sections") => PolicyInitTemplate {
            config: json!({
                "policies": {
                    "required_sections": ["runtimes", "tasks"]
                }
            }),
            yaml: "policies:\n  required_sections:\n    - runtimes\n    - tasks\n",
        },
        Some("provisioning") => PolicyInitTemplate {
            config: json!({
                "policies": {
                    "provisioning": {},
                    "adapter_bootstrap": {}
                }
            }),
            yaml: "policies:\n  provisioning: {}\n  adapter_bootstrap: {}\n\n# Replace the empty maps above with explicit approved sources, for example:\n# provisioning:\n#   node:\n#     source: brew\n#     approved_versions:\n#       - \"22\"\n#   java:\n#     source: apt\n#     package: openjdk-22-jdk\n#     approved_versions:\n#       - \"22\"\n# adapter_bootstrap:\n#   brew:\n#     source: brew-bootstrap\n#     approved_versions:\n#       - \"4.4\"\n",
        },
        Some("agent") => PolicyInitTemplate {
            config: json!({
                "policies": {
                    "agent": {
                        "require_safe_tasks": true,
                        "require_writable_paths": true
                    },
                    "exports": {
                        "require_agents_md": true
                    }
                }
            }),
            yaml: "policies:\n  agent:\n    require_safe_tasks: true\n    require_writable_paths: true\n  exports:\n    require_agents_md: true\n",
        },
        _ => PolicyInitTemplate {
            config: json!({ "policies": {} }),
            yaml: "policies: {}\n",
        },
    }
}

fn policy_init_command(path: Option<&Path>, preset: Option<&str>) -> String {
    let mut command = String::from("ota policy init");
    if let Some(preset) = preset {
        command.push_str(" --preset ");
        command.push_str(preset);
    }
    if let Some(path) = path {
        command.push(' ');
        command.push_str(&compact_path(path, "."));
    }
    command
}

fn policy_init_preview_command(path: Option<&Path>, preset: Option<&str>) -> String {
    let mut command = String::from("ota policy init");
    if let Some(preset) = preset {
        command.push_str(" --preset ");
        command.push_str(preset);
    }
    command.push_str(" --dry-run");
    if let Some(path) = path {
        command.push(' ');
        command.push_str(&compact_path(path, "."));
    }
    command
}

fn policy_init_preset_line(preset: Option<&str>) -> String {
    preset
        .map(|preset| format!("\n{} {}", paint_key("Preset:"), paint_code(preset)))
        .unwrap_or_default()
}

fn policy_init_available_presets_section(path: Option<&Path>, preset: Option<&str>) -> String {
    if preset.is_some() {
        return String::new();
    }

    let items = [
        policy_init_preview_command(path, Some("required-sections")),
        policy_init_preview_command(path, Some("provisioning")),
        policy_init_preview_command(path, Some("agent")),
    ];
    let mut output = format!("\n\n{}:", paint_section_title("Available presets"));
    for item in items {
        output.push_str(&format_next_timeline_step(&paint_code(&item)));
    }
    output
}

fn resolve_policy_init_path(path: Option<&Path>) -> Result<PathBuf, String> {
    let base = path.unwrap_or_else(|| Path::new("."));
    let is_explicit_policy_file = base
        .file_name()
        .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_FILE))
        || base
            .extension()
            .is_some_and(|ext| ext == "yaml" || ext == "yml")
        || base.is_file();

    if is_explicit_policy_file {
        let parent = base.parent().unwrap_or_else(|| Path::new("."));
        if parent
            .file_name()
            .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_DIR))
            && base
                .file_name()
                .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_FILE))
        {
            return Ok(base.to_path_buf());
        }
        return Err(policy_init_target_error(base));
    }

    if base.is_dir() {
        if base
            .file_name()
            .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_DIR))
        {
            return Ok(base.join(DEFAULT_POLICY_FILE));
        }
        return Ok(base.join(DEFAULT_POLICY_DIR).join(DEFAULT_POLICY_FILE));
    }

    if base
        .file_name()
        .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_DIR))
    {
        return Ok(base.join(DEFAULT_POLICY_FILE));
    }

    if base.exists() {
        return Err(policy_init_target_error(base));
    }

    Ok(base.join(DEFAULT_POLICY_DIR).join(DEFAULT_POLICY_FILE))
}

fn policy_init_review_command(target_path: &Path) -> String {
    let repo_root = target_path
        .parent()
        .and_then(Path::parent)
        .unwrap_or_else(|| Path::new("."));
    command_for_repo("ota policy", repo_root)
}

pub fn policy_init(
    path: Option<&Path>,
    preset: Option<&str>,
    dry_run: bool,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let target_path = match resolve_policy_init_path(path) {
        Ok(target_path) => target_path,
        Err(error) => {
            let path_display = path
                .map(|path| path.display().to_string())
                .unwrap_or_else(|| String::from("."));
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure_with_code(
                        command_message_failure_text(
                            "POLICY INIT",
                            "ota policy init",
                            "Policy pack target is invalid",
                            &error,
                            &[],
                        ),
                        2,
                    ),
                    OutputFormat::Json => CommandOutput {
                        stdout: to_json(&PolicyInitFailure {
                            ok: false,
                            path: &path_display,
                            written: false,
                            mode: "policy",
                            preset,
                            error: &error,
                            next: None,
                        }),
                        stderr: None,
                        exit_code: 2,
                    },
                },
                debug,
                vec![
                    String::from("DEBUG command=policy.init"),
                    format!("DEBUG invalid_target={path_display}"),
                ],
            );
        }
    };
    let path_display = target_path.display().to_string();
    let compact_path_display = compact_path(&target_path, DEFAULT_POLICY_FILE);
    let debug_lines = vec![
        String::from("DEBUG command=policy.init"),
        format!("DEBUG policy_path={path_display}"),
        format!("DEBUG preset={}", preset.unwrap_or("none")),
        format!("DEBUG dry_run={dry_run}"),
    ];
    let template = policy_init_template(preset);
    let yaml = String::from(template.yaml);

    if target_path.exists() {
        let review_command = policy_init_review_command(&target_path);
        let error_reason = format!(
            "`{}` already exists; refusing to overwrite the existing policy pack",
            compact_path_display
        );
        let error_text = format!(
            "{}{}",
            error_reason,
            format_next_timeline(&[
                String::from("review the existing policy pack"),
                format!("run `{review_command}` to inspect the active policy pack"),
            ])
        );
        return finalize_debug(
            match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    "POLICY INIT",
                    &compact_path_display,
                    "Policy pack already exists",
                    &error_text,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&PolicyInitFailure {
                    ok: false,
                    path: &path_display,
                    written: false,
                    mode: "policy",
                    preset,
                    error: &error_reason,
                    next: Some(&review_command),
                })),
            },
            debug,
            debug_lines,
        );
    }

    if dry_run {
        let write_command = policy_init_command(path, preset);
        let stdout = format!(
            "{}\n\n{}{}\n\n{}:\n{}{}{}",
            format_command_header("POLICY INIT PREVIEW", &compact_path_display),
            format_mode_line("dry-run (no write)"),
            policy_init_preset_line(preset),
            paint_section_title("Policy pack"),
            stylize_yaml_preview(yaml.trim_end()),
            policy_init_available_presets_section(path, preset),
            format_next_timeline(&[
                String::from("review the starter policy pack"),
                format!("run `{}` to write it", paint_code(&write_command)),
            ])
        );
        return finalize_debug(
            match format {
                OutputFormat::Text => CommandOutput::success(stdout),
                OutputFormat::Json => CommandOutput::success(to_json(&PolicyInitSuccess {
                    ok: true,
                    path: &path_display,
                    written: false,
                    mode: "policy",
                    preset,
                    config: template.config.clone(),
                })),
            },
            debug,
            debug_lines,
        );
    }

    if let Some(parent) = target_path.parent()
        && let Err(error) = fs::create_dir_all(parent)
    {
        let error = format!(
            "failed to create `{}`: {error}",
            compact_path(parent, DEFAULT_POLICY_DIR)
        );
        return finalize_debug(
            match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    "POLICY INIT",
                    &compact_path_display,
                    "Policy pack directory could not be created",
                    &error,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&PolicyInitFailure {
                    ok: false,
                    path: &path_display,
                    written: false,
                    mode: "policy",
                    preset,
                    error: &error,
                    next: None,
                })),
            },
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match fs::write(&target_path, &yaml) {
            Ok(()) => match format {
                OutputFormat::Text => {
                    let review_command = paint_code(&policy_init_review_command(&target_path));
                    let mut stdout = format!(
                        "{}\n\n{}",
                        format_command_header("POLICY INIT", &compact_path_display),
                        format_result_line(&format!("wrote {}", paint_code(&compact_path_display))),
                    );
                    if let Some(preset_line) = preset {
                        stdout.push_str(&format!(
                            "\n{} {}",
                            paint_key("Preset:"),
                            paint_code(preset_line)
                        ));
                    }
                    stdout.push_str(&format_next_timeline(&[
                        String::from("review the starter policy pack"),
                        format!("run `{review_command}` to inspect the active policy pack"),
                    ]));
                    CommandOutput::success(stdout)
                }
                OutputFormat::Json => CommandOutput::success(to_json(&PolicyInitSuccess {
                    ok: true,
                    path: &path_display,
                    written: true,
                    mode: "policy",
                    preset,
                    config: template.config,
                })),
            },
            Err(error) => {
                let error = format!("failed to write `{}`: {error}", compact_path_display);
                match format {
                    OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                        "POLICY INIT",
                        &compact_path_display,
                        "Policy pack could not be written",
                        &error,
                        &[],
                    )),
                    OutputFormat::Json => CommandOutput::failure(to_json(&PolicyInitFailure {
                        ok: false,
                        path: &path_display,
                        written: false,
                        mode: "policy",
                        preset,
                        error: &error,
                        next: None,
                    })),
                }
            }
        },
        debug,
        debug_lines,
    )
}

fn policy_reference_path(path: Option<&Path>, file_override: Option<&Path>) -> PathBuf {
    if let Some(file_override) = file_override {
        return file_override.to_path_buf();
    }

    if let Some(path) = path {
        return if path.is_dir() {
            path.join(DEFAULT_CONTRACT_FILE)
        } else {
            path.to_path_buf()
        };
    }

    env::current_dir()
        .unwrap_or_else(|_| PathBuf::from("."))
        .join(DEFAULT_CONTRACT_FILE)
}

fn compact_policy_path_relative_to_contract(contract_path: &Path, policy_path: &Path) -> String {
    let Some(repo_root) = contract_path.parent() else {
        return policy_path.display().to_string();
    };

    let repo_root = fs::canonicalize(repo_root).unwrap_or_else(|_| repo_root.to_path_buf());
    let absolute = normalized_display_path(policy_path);
    let absolute = fs::canonicalize(&absolute).unwrap_or(absolute);

    if let Ok(relative) = absolute.strip_prefix(&repo_root) {
        if relative.as_os_str().is_empty() {
            return String::from(".");
        }
        return format!("./{}", relative.display());
    }

    if let Some(relative) = relative_path_from(&repo_root, &absolute) {
        return relative.display().to_string();
    }

    absolute.display().to_string()
}

fn is_org_policy_pack_path(path: &Path) -> bool {
    path.file_name()
        .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_FILE))
        && path
            .parent()
            .and_then(Path::file_name)
            .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_POLICY_DIR))
}

fn repo_root_for_policy_pack(path: &Path) -> Option<&Path> {
    is_org_policy_pack_path(path)
        .then(|| path.parent().and_then(Path::parent))
        .flatten()
}

