    fn write_executable_script(path: &Path, body: &str) {
        fs::write(path, body).unwrap();
        let mut perms = fs::metadata(path).unwrap().permissions();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            perms.set_mode(0o755);
        }
        fs::set_permissions(path, perms).unwrap();
    }

    fn make_bootstrap_shims(dir: &Path) {
        let brew_log = dir.join("brew.log");
        let mise_log = dir.join("mise.log");
        let java_log = dir.join("java.log");

        let brew_script = format!(
            "#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"{}\"\n/bin/cat > \"{}\" <<'EOF'\n#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"{}\"\n/bin/cat > \"{}\" <<'EOJ'\n#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"{}\"\necho 'openjdk 22'\nexit 0\nEOJ\n/bin/chmod +x \"{}\"\nexit 0\nEOF\n/bin/chmod +x \"{}\"\nexit 0\n",
            brew_log.display(),
            dir.join("mise").display(),
            mise_log.display(),
            dir.join("java").display(),
            java_log.display(),
            dir.join("java").display(),
            dir.join("mise").display(),
        );
        write_executable_script(&dir.join("brew"), &brew_script);
    }

    #[test]
    fn build_env_report_uses_effective_execution_env_for_task() {
        let temp_dir = TempDir::new().unwrap();
        let contract_path = temp_dir.path().join("ota.yaml");
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: ephemeral
      env:
        CONTEXT_CACHE: ${OTA_WORKSPACE}/context-cache
      container:
        image: maven:3.9.14-eclipse-temurin-21-noble
      attachments:
        isolated_paths:
          - .m2
tasks:
  build:
    context: app
    run: mvn package
"#,
        )
        .unwrap();

        let report = build_env_report(&contract, &contract_path, Some("build")).unwrap();

        assert!(report.env.iter().any(|entry| {
            entry.name == "OTA_WORKSPACE"
                && entry.value.as_deref() == Some("/workspace")
                && entry.source == "execution"
        }));
        assert!(report.env.iter().any(|entry| {
            entry.name == "MAVEN_OPTS"
                && entry.value.as_deref() == Some("-Dmaven.repo.local=/workspace/.m2/repository")
                && entry.source == "execution"
        }));
        assert!(report.env.iter().any(|entry| {
            entry.name == "CONTEXT_CACHE"
                && entry.value.as_deref() == Some("/workspace/context-cache")
                && entry.source == "execution"
        }));
    }

    #[test]
    fn env_text_shows_properties_source_provenance() {
        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        let contract = parse_contract_str(
            &contract_path,
            r#"
version: 1
project:
  name: ota
env:
  vars:
    APP_PORT:
      required: true
  sources:
    - kind: properties
      path: app.properties
tasks:
  test:
    run: echo test
"#,
        )
        .unwrap();
        fs::write(fixture.path().join("app.properties"), "app.port=8080\n").unwrap();
        let original = std::env::var_os("APP_PORT");
        unsafe {
            std::env::remove_var("APP_PORT");
        }

        let report = build_env_report(&contract, &contract_path, None).unwrap();
        let rendered = strip_ansi_codes(&render_env_text(".", None, &report));

        assert!(rendered.contains("Source: source file"), "{rendered}");
        assert!(rendered.contains("Source Kind: properties"), "{rendered}");
        assert!(
            rendered.contains("Source Path: app.properties"),
            "{rendered}"
        );
        assert!(rendered.contains("Source Status: loaded"), "{rendered}");

        match original {
            Some(value) => unsafe { std::env::set_var("APP_PORT", value) },
            None => unsafe { std::env::remove_var("APP_PORT") },
        }
    }

