    #[test]
    fn up_preview_plan_lists_provisioning_actions_and_skips() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
runtimes:
  java: "21"
tools:
  node: "22"
tasks:
  setup:
    run: echo setup
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: false,
            provisioning: Some(crate::doctor::ProvisioningDiagnostics {
                plan: ProvisioningPlan::default(),
                request: ProvisioningBackendRequest {
                    actions: vec![
                        ProvisioningAction {
                            kind: ProvisioningActionKind::SelectSource,
                            target_kind: ProvisioningTargetKind::Runtime,
                            name: String::from("java"),
                            requested_version: String::from("21"),
                            normalized_requirement: None,
                            resolved_version: None,
                            package: None,
                            source: String::from("sdkman"),
                            source_config: None,
                            approved_version: Some(String::from("21")),
                            policy_match: None,
                        },
                        ProvisioningAction {
                            kind: ProvisioningActionKind::SelectSource,
                            target_kind: ProvisioningTargetKind::Tool,
                            name: String::from("node"),
                            requested_version: String::from("22"),
                            normalized_requirement: None,
                            resolved_version: None,
                            package: None,
                            source: String::from("brew"),
                            source_config: None,
                            approved_version: Some(String::from("22")),
                            policy_match: None,
                        },
                    ],
                },
            }),
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![Finding {
                severity: FindingSeverity::Error,
                summary: String::from("Missing runtime: java"),
                why: String::from("java is declared in the contract but is not available"),
                next: String::from("install `java` and rerun `ota doctor`"),
            }],
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            &preflight,
        );

        dbg!(&preview.plan.actions);
        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("provision `java` `21` via `sdkman`"))
        );
        assert!(
            preview
                .plan
                .skipped
                .contains(&String::from("skip `node`; already satisfies the contract"))
        );
        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("run task `setup`"))
        );
        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("re-check repo readiness"))
        );
    }

    #[test]
    fn up_preview_orders_pre_setup_setup_and_post_setup_service_phases_honestly() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
services:
  postgres:
    required: true
    manager:
      kind: compose
      name: local
      file: compose.yaml
      service: postgres
    endpoints:
      app:
        address: postgres
        port: 5432
    readiness:
      from: app
      kind: tcp
  app:
    required: true
    start: ./bin/start-app
    endpoints:
      host:
        address: 127.0.0.1
        port: 8080
    readiness:
      from: host
      kind: http
      path: /health
tasks:
  setup:
    requires_services:
      - postgres
    run: ./bin/setup
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: true,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: Vec::new(),
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            &preflight,
        );

        assert_eq!(
            preview.plan.actions,
            vec![
                String::from("start service `postgres` before `setup`"),
                String::from("verify service `postgres` readiness before `setup`"),
                String::from("run task `setup`"),
                String::from("start service `app` after `setup`"),
                String::from("verify service `app` readiness after `setup`"),
                String::from("re-check repo readiness"),
            ]
        );
    }

    #[test]
    fn finding_targets_provisioning_action_strips_context_suffix() {
        let finding = Finding {
            severity: FindingSeverity::Error,
            summary: String::from("Version mismatch for runtime: java (context remote-app)"),
            why: String::from("java is declared in the contract but is not available"),
            next: String::from("install `java` and rerun `ota doctor`"),
        };
        let action = ProvisioningAction {
            kind: ProvisioningActionKind::SelectSource,
            target_kind: ProvisioningTargetKind::Runtime,
            name: String::from("java"),
            requested_version: String::from("21"),
            normalized_requirement: None,
            resolved_version: None,
            package: None,
            source: String::from("sdkman"),
            source_config: None,
            approved_version: Some(String::from("21")),
            policy_match: None,
        };
        let other_action = ProvisioningAction {
            name: String::from("node"),
            ..action.clone()
        };

        assert_eq!(
            super::provisionable_target_key_for_finding(&finding),
            Some(String::from("runtime:java"))
        );
        assert!(super::finding_targets_provisioning_action(
            &finding, &action
        ));
        assert!(!super::finding_targets_provisioning_action(
            &finding,
            &other_action
        ));
    }

    #[test]
    fn up_preview_does_not_treat_probe_failures_as_provisionable() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
tools:
  npm: "*"
tasks:
  setup:
    run: echo setup
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: false,
            provisioning: Some(crate::doctor::ProvisioningDiagnostics {
                plan: ProvisioningPlan::default(),
                request: ProvisioningBackendRequest {
                    actions: vec![ProvisioningAction {
                        kind: ProvisioningActionKind::SelectSource,
                        target_kind: ProvisioningTargetKind::Tool,
                        name: String::from("npm"),
                        requested_version: String::from("*"),
                        normalized_requirement: None,
                        resolved_version: None,
                        package: None,
                        source: String::from("choco"),
                        source_config: None,
                        approved_version: Some(String::from("*")),
                        policy_match: None,
                    }],
                },
            }),
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![Finding {
                severity: FindingSeverity::Error,
                summary: String::from("Tool probe failed: npm"),
                why: String::from(
                    "ota probed `C:\\node\\npm.cmd` with `npm --version`, but the command exited with code 1 before ota could read a version",
                ),
                next: String::from(
                    "run `npm --version` directly, inspect `C:\\node\\npm.cmd`, and make sure the probe succeeds before rerunning `ota doctor`",
                ),
            }],
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            &preflight,
        );

        assert!(
            !preview
                .plan
                .actions
                .contains(&String::from("provision `npm` `*` via `choco`"))
        );
        assert!(
            preview
                .plan
                .skipped
                .contains(&String::from("skip `npm`; already satisfies the contract"))
        );
    }

