    #[test]
    fn collect_validate_warnings_reports_cross_boundary_depends_on() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: node:24-bookworm
    verify:
      backend: native
tasks:
  setup:
    context: app
    run: npm install
  build:
    context: verify
    run: npm run build
    depends_on:
      - setup
"#,
        )
        .unwrap();

        let warnings = collect_validate_warnings(&contract);

        assert!(warnings.iter().any(|warning| {
            warning
                .contains("task `build` depends_on `setup` across different execution boundaries")
                && warning.contains("only durable external side effects survive")
        }));
    }

    #[test]
    fn render_validate_success_output_includes_warning_section() {
        let advisories = vec![ContractAdvisory::DependsOnBoundary(
            crate::validator::DependsOnBoundaryAdvisory {
                parent_task: String::from("build"),
                dependency_task: String::from("setup"),
                parent: TaskExecutionBoundary {
                    context_name: Some(String::from("verify")),
                    backend: Backend::Native,
                    lifecycle: None,
                    backend_binding: None,
                },
                dependency: TaskExecutionBoundary {
                    context_name: Some(String::from("app")),
                    backend: Backend::Container,
                    lifecycle: Some(Lifecycle::Persistent),
                    backend_binding: None,
                },
            },
        )];
        let rendered = strip_ansi_codes(&render_validate_success_output(
            Path::new("/tmp/ota.yaml"),
            None,
            "./ota.yaml",
            &advisories,
        ));

        assert!(rendered.contains("Warnings"));
        assert!(rendered.contains("`build` → `setup`"));
        assert!(rendered.contains("Drift: context: verify → app"));
        assert!(rendered.contains("lifecycle: none → persistent"));
        assert!(rendered.contains("Why: only durable external side effects survive this edge"));
        assert!(rendered.contains("Next:"));
    }

    #[test]
    fn structured_validation_error_details_clarifies_invalid_isolated_path_entries() {
        let why = String::from(
            "`execution.contexts.development.attachments.isolated_paths` entries must be relative paths without `..` or absolute prefixes",
        );
        let next = vec![
            String::from("repair `./ota.yaml`"),
            String::from("rerun `ota validate`"),
        ];

        let (why_lines, next_steps) =
            super::structured_validation_error_details(&[why], &next).unwrap();

        assert_eq!(
            why_lines[0],
            "`execution.contexts.development.attachments.isolated_paths` contains an invalid isolated path"
        );
        assert!(why_lines.contains(&String::from(
            "`attachments.isolated_paths` must stay relative to the repo root"
        )));
        assert!(why_lines.contains(&String::from(
            "absolute paths and `..` segments are rejected"
        )));
        assert_eq!(
            next_steps[0],
            "replace the invalid entry with a repo-relative path like `node_modules`, `.next`, `.m2`, or `.npm`"
        );
        assert_eq!(next_steps[1], "rerun `ota validate`");
    }

    #[test]
    fn doctor_depends_on_boundary_finding_renders_compact_edge_shape() {
        let mut rendered = String::new();
        assert!(super::render_depends_on_boundary_doctor_finding(
            &mut rendered,
            FindingSeverity::Warn,
            "Task `build` depends_on `setup` across different execution boundaries",
            "execution differs across the dependency edge (context: verify -> app, lifecycle: none -> persistent) so only durable external side effects survive; in-process, session-local, and container-local prep does not carry across",
            "align both tasks to one execution boundary, or make the shared state durable",
            None,
        ));

        let rendered = strip_ansi_codes(&rendered);
        assert!(rendered.contains("`build` → `setup`"));
        assert!(rendered.contains("Why: only durable external side effects survive this edge"));
        assert!(rendered.contains("Drift: context: verify → app, lifecycle: none → persistent"));
        assert!(rendered.contains(
            "Next: align both tasks to one execution boundary, or make the shared state durable"
        ));
    }

    #[test]
    fn phase_execution_contexts_use_matching_named_contexts() {
        let contract = parse_contract_str(
            Path::new("/tmp/ota.yaml"),
            r#"
version: 1
project:
  name: topology-example
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/dev:latest
        resources:
          memory:
            minimum: 2GiB
            default: 3GiB
    remote-db:
      backend: remote
      remote:
        provider: ssh
        target: sandbox-dev
        cwd: /tmp
"#,
        )
        .unwrap();

        let doctor_container = super::doctor_phase_execution_context(
            &contract,
            Path::new("/tmp/ota.yaml"),
            DoctorMode::Container,
        );
        assert_eq!(doctor_container.context.as_deref(), Some("app"));
        assert_eq!(
            doctor_container.container_memory_bytes,
            Some(parse_memory_size_bytes("3GiB").unwrap())
        );

        let doctor_remote = super::doctor_phase_execution_context(
            &contract,
            Path::new("/tmp/ota.yaml"),
            DoctorMode::Remote,
        );
        assert_eq!(doctor_remote.context.as_deref(), Some("remote-db"));
        assert_eq!(doctor_remote.provider.as_deref(), Some("ssh"));
        assert_eq!(doctor_remote.cwd.as_deref(), Some("/tmp"));

        let provisioning_container = super::provisioning_phase_execution_context(
            &contract,
            Path::new("/tmp/ota.yaml"),
            &ProvisioningExecutionTarget::Container {
                image: String::from("ghcr.io/ota/dev:latest"),
                engine: String::from("docker"),
                lifecycle: Lifecycle::Ephemeral,
                container_name: None,
            },
        );
        assert_eq!(provisioning_container.context.as_deref(), Some("app"));
        assert_eq!(
            provisioning_container.container_memory_bytes,
            Some(parse_memory_size_bytes("3GiB").unwrap())
        );

        let provisioning_remote = super::provisioning_phase_execution_context(
            &contract,
            Path::new("/tmp/ota.yaml"),
            &ProvisioningExecutionTarget::Remote {
                provider: String::from("ssh"),
                provider_command: None,
                target: String::from("sandbox-dev"),
                cwd: Some(String::from("/tmp")),
                ssh: None,
                context_name: None,
            },
        );
        assert_eq!(provisioning_remote.context.as_deref(), Some("remote-db"));
        assert_eq!(provisioning_remote.provider.as_deref(), Some("ssh"));
        assert_eq!(provisioning_remote.cwd.as_deref(), Some("/tmp"));
    }

    #[test]
    fn execution_summary_from_contract_includes_named_contexts() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(&contract_path, "kind: ota").unwrap();
        let contract = parse_contract_str(
            &contract_path,
            r#"
version: 1
project:
  name: topology-example
execution:
  default_context: app
  preferred: container
  lifecycle: persistent
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: maven:3.9.14-eclipse-temurin-21-noble
      attachments:
        compose:
          - local
    host:
      backend: native
"#,
        )
        .unwrap();

        let execution = ExecutionSummary::from_contract(&contract, &contract_path).unwrap();

        assert_eq!(execution.default_context, Some("app"));
        assert_eq!(execution.contexts.len(), 2);
        assert_eq!(execution.contexts[0].name, "app");
        assert_eq!(execution.contexts[0].backend, "container");
        assert_eq!(execution.contexts[0].lifecycle, Some("persistent"));
        assert_eq!(
            execution.contexts[0]
                .container
                .as_ref()
                .map(|container| container.image),
            Some("maven:3.9.14-eclipse-temurin-21-noble")
        );
        assert_eq!(
            execution.contexts[0]
                .attachments
                .as_ref()
                .map(|attachments| attachments.compose.clone()),
            Some(vec!["local"])
        );
        assert_eq!(execution.contexts[1].name, "host");
        assert_eq!(execution.contexts[1].backend, "native");
    }

    #[test]
    fn execution_plan_text_prioritizes_selected_execution_and_other_contexts() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(&contract_path, "kind: ota").unwrap();
        let contract = parse_contract_str(
            &contract_path,
            r#"
version: 1
project:
  name: topology-example
execution:
  default_context: development:ctx
  contexts:
    development:ctx:
      backend: container
      lifecycle: persistent
      container:
        image: node:24-bookworm
      attachments:
        isolated_paths:
          - node_modules
          - .next
    verify:ctx:
      backend: container
      lifecycle: ephemeral
      container:
        image: node:24-bookworm
      attachments:
        isolated_paths:
          - node_modules
          - .next
"#,
        )
        .unwrap();

        let execution = ExecutionSummary::from_contract(&contract, &contract_path).unwrap();
        let text = strip_ansi_codes(&super::render_execution_plan_text(
            "./ota.yaml",
            &contract_path,
            &ContractIdentity {
                version: 1,
                project: crate::output::ContractIdentityProject {
                    name: String::from("topology-example"),
                    project_type: None,
                },
                metadata: crate::output::ContractIdentityMetadata::default(),
                execution: crate::output::ContractIdentityExecution::default(),
                counts: crate::output::ContractIdentityCounts {
                    runtimes: 0,
                    tools: 0,
                    env: 0,
                    services: 0,
                    checks: 0,
                    tasks: 0,
                    repos: None,
                    policies: None,
                },
            },
            Some(&execution),
            &ExecutionPlanResolved {
                backend: String::from("container"),
                backend_source: String::from("default context"),
                lifecycle: Some(String::from("persistent")),
                lifecycle_source: Some(String::from("context lifecycle")),
                image: Some(String::from("node:24-bookworm")),
                engine: Some(String::from("docker")),
                engine_candidates: Vec::new(),
                provider: None,
                target: Some(String::from("ota-4e6691d00559e2b3")),
                target_strategy: String::from("persistent"),
                cwd: None,
            },
            None,
        ));

        assert!(text.contains("\n\nSelected Execution\n"));
        assert!(text.contains("\n» Backend: `container`"));
        assert!(text.contains("\n» Lifecycle: `persistent`"));
        assert!(text.contains("\n» Image: `node:24-bookworm`"));
        assert!(text.contains("\n» Engine: `docker`"));
        assert!(text.contains("\n» Context: `development:ctx` (default)"));
        assert!(text.contains("\n» Target: `ota-4e6691d00559e2b3`"));
        assert!(text.contains("\n» Isolation: `/workspace/node_modules`, `/workspace/.next`"));
        assert!(text.contains("\n\nOther Contexts\n"));
        assert!(text.contains(
            "\n» `verify:ctx`\n  container, ephemeral, image=node:24-bookworm, isolated=/workspace/node_modules+/workspace/.next"
        ));
        assert!(!text.contains("\n\nPlan\n"));
        assert!(!text.contains("\n\nAvailable Contexts\n"));
    }

    #[test]
    fn doctor_text_container_primary_blocker_renders_image_detail_line() {
        let report = DoctorReport {
            ok: false,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![Finding {
                severity: FindingSeverity::Error,
                summary: String::from("Missing runtime: java"),
                why: String::from(
                    "java is declared in the contract but is not available inside container image `jdxcode/mise:latest`",
                ),
                next: String::from(
                    "update `execution.backends.container.image` (currently `jdxcode/mise:latest`) so `java` is available, then rerun `ota doctor --mode container`",
                ),
            }],
        };
        let summary = super::DoctorSummary {
            verdict: super::DoctorVerdict::NotReady,
            agent_verdict: super::DoctorVerdict::Ready,
            error_count: 1,
            warn_count: 0,
            info_count: 0,
            primary_blocker: Some(super::DoctorPrimaryBlocker {
                severity: FindingSeverity::Error,
                summary: String::from("Missing runtime: java"),
                why: String::from(
                    "java is declared in the contract but is not available inside container image `jdxcode/mise:latest`",
                ),
                next: String::from(
                    "update `execution.backends.container.image` (currently `jdxcode/mise:latest`) so `java` is available, then rerun `ota doctor --mode container`",
                ),
                provenance: None,
                provenance_key: None,
            }),
        };

        let text = strip_ansi_codes(&render_report_section(
            "DOCTOR",
            "./ota.yaml",
            None,
            None,
            None,
            Some(DoctorMode::Container),
            &report,
            Some(&summary),
        ));

        assert!(
            text.contains("➤ Primary Blocker Java is missing from the configured container image")
        );
        assert!(text.contains("Why:\n  » `java` is declared in the contract"));
        assert!(text.contains("  » it is not available in the configured container image"));
        assert!(text.contains("  » `execution.backends.container.image = jdxcode/mise:latest`"));
        assert!(!text.contains("inside container image `jdxcode/mise:latest`"));
        assert!(!text.contains("(currently `jdxcode/mise:latest`)"));
        assert!(text.contains(
            "Next:\n  » update `execution.backends.container.image` so `java` is available"
        ));
        assert!(text.contains("  » rerun `ota doctor --mode container`"));
    }

