    #[test]
    fn run_execution_receipt_reports_truthful_context_for_native_and_container_overrides() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  test:
    context: app
    run: echo test
"#,
        )
        .unwrap();

        let native_receipt = run_execution_receipt(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides {
                backend: Some(Backend::Native),
                lifecycle: None,
                host_port: None,
                memory: None,
            },
            "test",
            None,
            &[ExecutedTaskStep {
                name: String::from("test"),
                exit_code: 0,
                relation: TaskExecutionRelation::Requested,
                generation: 0,
                execution_note: None,
            }],
            &[],
            &[],
            0,
            true,
            None,
            None,
            None,
        );
        assert_eq!(native_receipt.backend.as_deref(), Some("native"));
        assert_eq!(native_receipt.context.as_deref(), Some("host"));
        assert_eq!(native_receipt.lifecycle, None);

        let container_receipt = run_execution_receipt(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides {
                backend: Some(Backend::Container),
                lifecycle: Some(Lifecycle::Persistent),
                host_port: None,
                memory: None,
            },
            "test",
            None,
            &[ExecutedTaskStep {
                name: String::from("test"),
                exit_code: 0,
                relation: TaskExecutionRelation::Requested,
                generation: 0,
                execution_note: None,
            }],
            &[],
            &[],
            0,
            true,
            None,
            None,
            None,
        );

        assert_eq!(container_receipt.backend.as_deref(), Some("container"));
        assert_eq!(container_receipt.context.as_deref(), Some("app"));
        assert_eq!(container_receipt.lifecycle.as_deref(), Some("persistent"));
        assert_eq!(
            container_receipt.image.as_deref(),
            Some("ghcr.io/ota/dev:latest")
        );
        assert!(
            container_receipt
                .target
                .as_deref()
                .is_some_and(|target| target.starts_with("ota-"))
        );

        let native_override_receipt = run_execution_receipt(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides {
                backend: Some(Backend::Native),
                lifecycle: Some(Lifecycle::Persistent),
                host_port: None,
                memory: None,
            },
            "test",
            None,
            &[ExecutedTaskStep {
                name: String::from("test"),
                exit_code: 0,
                relation: TaskExecutionRelation::Requested,
                generation: 0,
                execution_note: None,
            }],
            &[],
            &[],
            0,
            true,
            None,
            None,
            None,
        );
        assert_eq!(native_override_receipt.backend.as_deref(), Some("native"));
        assert_eq!(native_override_receipt.context.as_deref(), Some("host"));
        assert_eq!(
            native_override_receipt.lifecycle.as_deref(),
            Some("persistent")
        );
        let rendered = render_execution_receipt_summary_block(
            &native_override_receipt,
            Some("test"),
            "RUN SUMMARY",
        );
        assert!(rendered.contains("Lifecycle:"));
        assert!(rendered.contains("persistent"));
        assert!(
            rendered.contains("requested `--lifecycle persistent` is advisory in native mode only")
        );
    }

