    #[test]
    fn task_exit_failure_text_explains_exit_137() {
        let rendered = strip_ansi_codes(&super::render_task_exit_failure_text(
            "./ota.yaml",
            "setup:dev",
            None,
            137,
            None,
            &[String::from(
                "run `ota tasks --use` to inspect runnable task usage",
            )],
            Some("RUN SUMMARY\nStatus:      failed"),
            None,
        ));

        assert!(
            rendered.contains("`setup:dev` exited with code 137"),
            "{rendered}"
        );
        assert!(
            rendered.contains("task `setup:dev` returned non-zero exit code `137`"),
            "{rendered}"
        );
        assert!(
            rendered.contains("exit code `137` usually means the process was killed (SIGKILL), often due to OOM or container runtime termination"),
            "{rendered}"
        );
    }

    #[test]
    fn task_exit_failure_text_explains_dependency_failure_for_requested_task() {
        let rendered = strip_ansi_codes(&super::render_task_exit_failure_text(
            "./ota.yaml",
            "dev",
            Some("dev:clean"),
            1,
            None,
            &[],
            Some("RUN SUMMARY\nTask:        dev:clean\nStatus:      failed"),
            None,
        ));

        assert!(rendered.contains("Requested: dev:clean"), "{rendered}");
        assert!(rendered.contains("Failed Step: dev"), "{rendered}");
        assert!(
            rendered.contains(
                "requested task `dev:clean` failed because depends_on task `dev` returned a non-zero exit code"
            ),
            "{rendered}"
        );
    }

