fn compact_path_relative_to(path: &Path, fallback: &str, current_dir: Option<&Path>) -> String {
    let Some(current_dir) = current_dir else {
        return path.display().to_string();
    };
    let current_dir = fs::canonicalize(current_dir).unwrap_or_else(|_| current_dir.to_path_buf());
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        current_dir.join(path)
    };
    let absolute = fs::canonicalize(&absolute).unwrap_or(absolute);
    if let Ok(relative) = absolute.strip_prefix(&current_dir) {
        if relative.as_os_str().is_empty() {
            return String::from(".");
        }
        return format!("./{}", relative.display());
    }
    let absolute_display = if absolute.is_absolute() {
        absolute.display().to_string()
    } else {
        String::new()
    };
    if let Some(relative) = shorter_relative_path(&current_dir, &absolute, &absolute_display) {
        return relative;
    }
    if absolute.is_absolute() {
        return absolute_display;
    }

    let tail = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(fallback);
    match path
        .parent()
        .and_then(|parent| parent.file_name())
        .and_then(|name| name.to_str())
    {
        Some(parent) => format!("./{parent}/{tail}"),
        None => tail.to_string(),
    }
}

fn shorter_relative_path(base: &Path, target: &Path, absolute_display: &str) -> Option<String> {
    let relative = relative_path_from(base, target)?;
    let rendered = relative.display().to_string();
    if rendered.is_empty() || rendered.len() >= absolute_display.len() {
        return None;
    }
    Some(rendered)
}

fn relative_path_from(base: &Path, target: &Path) -> Option<PathBuf> {
    use std::path::Component;

    if !base.is_absolute() || !target.is_absolute() {
        return None;
    }

    let base_components = base.components().collect::<Vec<_>>();
    let target_components = target.components().collect::<Vec<_>>();

    let mut shared = 0usize;
    while shared < base_components.len()
        && shared < target_components.len()
        && match (base_components[shared], target_components[shared]) {
            (Component::Prefix(left), Component::Prefix(right)) => left == right,
            (left, right) => left == right,
        }
    {
        shared += 1;
    }

    if shared == 0 {
        return None;
    }

    let mut relative = PathBuf::new();
    for component in base_components.iter().skip(shared) {
        if !matches!(component, Component::Normal(_)) {
            continue;
        }
        relative.push("..");
    }
    for component in target_components.iter().skip(shared) {
        relative.push(component.as_os_str());
    }

    if relative.as_os_str().is_empty() {
        Some(PathBuf::from("."))
    } else {
        Some(relative)
    }
}

fn command_for_contract(command: &str, contract_path: &Path) -> String {
    if contract_path_matches_current_dir(contract_path) {
        command.to_string()
    } else {
        let display_path = compact_path(
            &normalized_display_path(contract_path),
            DEFAULT_CONTRACT_FILE,
        );
        format!("{command} {display_path}")
    }
}

fn command_for_repo_contract_target(command: &str, contract_path: &Path) -> String {
    if contract_path
        .file_name()
        .is_some_and(|name| name == std::ffi::OsStr::new(DEFAULT_CONTRACT_FILE))
    {
        return command_for_repo(
            command,
            contract_path.parent().unwrap_or_else(|| Path::new(".")),
        );
    }

    command_for_contract(command, contract_path)
}

fn command_for_repo_from_contract_path(command: &str, contract_path: &Path) -> String {
    if contract_path.is_dir() {
        return command_for_repo(command, contract_path);
    }

    command_for_repo(
        command,
        contract_path.parent().unwrap_or_else(|| Path::new(".")),
    )
}

fn command_for_repo(command: &str, repo_path: &Path) -> String {
    if std::env::current_dir().ok().is_some_and(|current_dir| {
        let current_dir = fs::canonicalize(&current_dir).unwrap_or(current_dir);
        let target = if repo_path.is_absolute() {
            repo_path.to_path_buf()
        } else {
            current_dir.join(repo_path)
        };
        let target = fs::canonicalize(&target).unwrap_or(target);
        target == current_dir
    }) {
        command.to_string()
    } else {
        format!("{command} {}", compact_repo_path(repo_path))
    }
}

fn command_for_workspace(command: &str, workspace_path: &Path) -> String {
    if workspace_path_matches_current_dir(workspace_path) {
        command.to_string()
    } else {
        format!("{command} {}", compact_workspace_path(workspace_path))
    }
}

fn contract_path_matches_current_dir(contract_path: &Path) -> bool {
    std::env::current_dir().ok().is_some_and(|current_dir| {
        let current_dir = fs::canonicalize(&current_dir).unwrap_or(current_dir);
        let target = normalized_display_path(contract_path);
        target
            .parent()
            .is_some_and(|contract_root| current_dir.starts_with(contract_root))
    })
}

fn workspace_path_matches_current_dir(workspace_path: &Path) -> bool {
    std::env::current_dir().ok().is_some_and(|current_dir| {
        let target = if workspace_path.is_absolute() {
            workspace_path.to_path_buf()
        } else {
            current_dir.join(workspace_path)
        };
        target == current_dir.join(DEFAULT_WORKSPACE_FILE)
    })
}

fn duplicate_member<'a>(members: &'a [String]) -> Option<&'a str> {
    let mut seen = BTreeSet::new();
    for member in members {
        if !seen.insert(member.as_str()) {
            return Some(member);
        }
    }
    None
}

fn render_workspace_init_discovery_sections(
    stdout: &mut String,
    included: &[WorkspaceInitRepoSummary],
    missing_contract: &[WorkspaceInitRepoSummary],
) {
    stdout.push_str(&format!("\n\n{}:", paint_section_title("Included repos")));
    if included.is_empty() {
        stdout.push_str(&format!("\n{}  none", info_bullet()));
    } else {
        for repo in included {
            stdout.push_str(&format!(
                "\n{}  {} ({})",
                info_bullet(),
                repo.name,
                repo.path
            ));
        }
    }

    stdout.push_str(&format!(
        "\n\n{}:",
        paint_section_title("Skipped (missing ota.yaml)")
    ));
    if missing_contract.is_empty() {
        stdout.push_str(&format!("\n{}  none", info_bullet()));
    } else {
        for repo in missing_contract {
            stdout.push_str(&format!(
                "\n{}  {} ({})",
                info_bullet(),
                repo.name,
                repo.path
            ));
        }
        stdout.push_str(&format_next_timeline(&[
                String::from(
                    "or run `ota workspace init --bootstrap` on first workspace creation to auto-provision missing repo contracts and write `ota.workspace.yaml`",
                ),
                String::from(
                    "run `ota workspace detect --write` after repo contracts exist to refresh `ota.workspace.yaml`",
                ),
                String::from("or create missing repo contracts with `ota init <repo-path>`"),
                String::from("or preview repo contracts with `ota init --dry-run <repo-path>`"),
            ]));
    }
}

fn render_workspace_auto_provision_sections(
    stdout: &mut String,
    provisioned: &[WorkspaceInitRepoSummary],
    skipped: &[(WorkspaceInitRepoSummary, String)],
) {
    if provisioned.is_empty() && skipped.is_empty() {
        return;
    }

    stdout.push_str(&format!(
        "\n\n{}:",
        paint_section_title("Auto-provisioned repo contracts")
    ));
    if provisioned.is_empty() {
        stdout.push_str(&format!("\n{}  none", info_bullet()));
    } else {
        for repo in provisioned {
            stdout.push_str(&format!(
                "\n{}  {} ({})",
                info_bullet(),
                repo.name,
                repo.path
            ));
        }
    }

    if !skipped.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}:",
            paint_section_title("Auto-provision skipped")
        ));
        for (repo, reason) in skipped {
            stdout.push_str(&format!(
                "\n{}  {} ({}): {}",
                info_bullet(),
                repo.name,
                repo.path,
                reason
            ));
        }
    }
}

fn render_workspace_repo_rewrite_sections(
    stdout: &mut String,
    rewritten: &[WorkspaceInitRepoSummary],
    skipped: &[(WorkspaceInitRepoSummary, String)],
) {
    if rewritten.is_empty() && skipped.is_empty() {
        return;
    }

    stdout.push_str(&format!(
        "\n\n{}:",
        paint_section_title("Rewritten repo contracts")
    ));
    if rewritten.is_empty() {
        stdout.push_str(&format!("\n{}  none", info_bullet()));
    } else {
        for repo in rewritten {
            stdout.push_str(&format!(
                "\n{}  {} ({})",
                info_bullet(),
                repo.name,
                repo.path
            ));
        }
    }

    if !skipped.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}:",
            paint_section_title("Repo rewrite skipped")
        ));
        for (repo, reason) in skipped {
            stdout.push_str(&format!(
                "\n{}  {} ({}): {}",
                info_bullet(),
                repo.name,
                repo.path,
                reason
            ));
        }
    }
}

fn render_workspace_init_merge_section(
    stdout: &mut String,
    title: &str,
    additions: &[WorkspaceInitRepoSummary],
) {
    stdout.push_str(&format!("\n\n{}:", paint_section_title(title)));
    if additions.is_empty() {
        stdout.push_str(&format!("\n{}  none", info_bullet()));
    } else {
        for repo in additions {
            stdout.push_str(&format!(
                "\n{}  {} ({})",
                info_bullet(),
                repo.name,
                repo.path
            ));
        }
    }
}

fn build_workspace_init_merge_state(
    workspace_path: &Path,
    draft: &WorkspaceInitDraft,
) -> Result<WorkspaceInitMergeState, String> {
    let contents = fs::read_to_string(workspace_path).map_err(|error| {
        format!(
            "failed to read `{}`: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let mut document: YamlValue = serde_yaml::from_str(&contents).map_err(|error| {
        format!(
            "failed to parse existing workspace contract `{}` for merge: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let repos = document
        .as_mapping()
        .and_then(|root| root.get(YamlValue::String(String::from("repos"))))
        .and_then(YamlValue::as_mapping)
        .ok_or_else(|| {
            format!(
                "existing workspace contract `{}` must contain a `repos` mapping for merge",
                compact_workspace_path(workspace_path)
            )
        })?;

    let mut additions = Vec::new();
    for repo in &draft.included {
        if !repos.contains_key(YamlValue::String(repo.name.clone())) {
            additions.push(repo.clone());
        }
    }

    let root = document.as_mapping_mut().ok_or_else(|| {
        format!(
            "existing workspace contract `{}` must be a mapping for merge",
            compact_workspace_path(workspace_path)
        )
    })?;
    let repos_key = YamlValue::String(String::from("repos"));
    if !root.contains_key(&repos_key) {
        root.insert(repos_key.clone(), YamlValue::Mapping(Mapping::new()));
    }
    let repos = root
        .get_mut(&repos_key)
        .and_then(YamlValue::as_mapping_mut)
        .ok_or_else(|| {
            format!(
                "existing workspace contract `{}` must contain a `repos` mapping for merge",
                compact_workspace_path(workspace_path)
            )
        })?;

    for repo in &additions {
        let repo_key = YamlValue::String(repo.name.clone());
        let spec =
            draft.contract.repos.get(&repo.name).ok_or_else(|| {
                format!("internal merge error: missing repo spec `{}`", repo.name)
            })?;
        let mut spec_map = Mapping::new();
        spec_map.insert(
            YamlValue::String(String::from("path")),
            YamlValue::String(spec.path.clone()),
        );
        spec_map.insert(
            YamlValue::String(String::from("required")),
            YamlValue::Bool(spec.required),
        );
        repos.insert(repo_key, YamlValue::Mapping(spec_map));
    }

    let yaml = serde_yaml::to_string(&document).map_err(|error| {
        format!(
            "failed to serialize merged workspace contract `{}`: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let contract =
        parse_workspace_contract_str(workspace_path, &yaml).map_err(|error| error.to_string())?;
    validate_workspace_contract(workspace_path, &contract).map_err(|error| error.to_string())?;
    Ok(WorkspaceInitMergeState {
        yaml,
        contract,
        comparison: WorkspaceInitComparison {
            existing_contract: true,
            additions,
        },
    })
}

fn apply_workspace_init_merge(
    workspace_path: &Path,
    draft: &WorkspaceInitDraft,
) -> Result<WorkspaceInitMergeState, String> {
    let state = build_workspace_init_merge_state(workspace_path, draft)?;
    if !state.comparison.additions.is_empty() {
        fs::write(workspace_path, &state.yaml).map_err(|error| {
            format!(
                "failed to write `{}`: {error}",
                compact_workspace_path(workspace_path)
            )
        })?;
    }
    Ok(state)
}

fn resolve_workspace_init_target(path: Option<&Path>) -> Result<(PathBuf, PathBuf), String> {
    match path {
        Some(path)
            if path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name == DEFAULT_WORKSPACE_FILE) =>
        {
            let root = path
                .parent()
                .filter(|parent| !parent.as_os_str().is_empty())
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from("."));
            Ok((root, path.to_path_buf()))
        }
        Some(path) if path.is_dir() => {
            let root = path.to_path_buf();
            let workspace_path = root.join(DEFAULT_WORKSPACE_FILE);
            Ok((root, workspace_path))
        }
        Some(path) => Err(format!(
            "workspace init path must be a directory or `{DEFAULT_WORKSPACE_FILE}` target path: {}",
            path.display()
        )),
        None => {
            let root = std::env::current_dir()
                .map_err(|error| format!("failed to resolve current directory: {error}"))?;
            let workspace_path = root.join(DEFAULT_WORKSPACE_FILE);
            Ok((root, workspace_path))
        }
    }
}

fn build_workspace_init_draft(workspace_root: &Path) -> Result<WorkspaceInitDraft, String> {
    let mut candidates = discover_workspace_candidates(workspace_root)?;
    let has_any_candidates = !candidates.is_empty();
    candidates.sort_by(|left, right| left.path.cmp(&right.path));

    let mut included = Vec::new();
    let mut missing_contract = Vec::new();
    for candidate in candidates {
        if candidate.has_contract {
            included.push(WorkspaceInitRepoSummary {
                name: candidate.name,
                path: candidate.path,
            });
        } else {
            missing_contract.push(WorkspaceInitRepoSummary {
                name: candidate.name,
                path: candidate.path,
            });
        }
    }

    if !has_any_candidates {
        return Err(format!(
            "workspace init could not find any repos to bootstrap; add repo contracts first before writing `ota.workspace.yaml`{}",
            format_next_timeline(&[
                String::from("create repo contracts with `ota init <repo-path>`"),
                String::from("or preview repo contracts with `ota detect --dry-run <repo-path>`"),
                String::from(
                    "then run `ota workspace detect --write` or `ota workspace init` after repo contracts exist"
                ),
            ]),
        ));
    }

    let mut repos = BTreeMap::new();
    for repo in &included {
        repos.insert(
            repo.name.clone(),
            WorkspaceInitRepoSpec {
                path: repo.path.clone(),
                required: true,
            },
        );
    }

    let workspace_name = workspace_root
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or("ota-workspace")
        .to_string();

    Ok(WorkspaceInitDraft {
        contract: WorkspaceInitContract {
            version: 1,
            workspace: WorkspaceInitWorkspace {
                name: workspace_name,
                description: None,
            },
            repos,
        },
        included,
        missing_contract,
    })
}

fn auto_provision_workspace_repo_contracts(
    workspace_root: &Path,
    missing_contract: &[WorkspaceInitRepoSummary],
) -> WorkspaceAutoProvisionResult {
    let mut result = WorkspaceAutoProvisionResult {
        provisioned: Vec::new(),
        skipped: Vec::new(),
    };

    for repo in missing_contract {
        let repo_root = workspace_root.join(&repo.path);
        let contract_path = repo_root.join(DEFAULT_CONTRACT_FILE);
        if contract_path.is_file() {
            result.provisioned.push(repo.clone());
            continue;
        }

        let report = match detect_repo(&repo_root) {
            Ok(report) => report,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("detect failed: {error}")));
                continue;
            }
        };

        let high_confidence = report.high_confidence_contract();
        let high_confidence_yaml = match serde_yaml::to_string(&high_confidence) {
            Ok(yaml) => yaml,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("serialize failed: {error}")));
                continue;
            }
        };

        let yaml_to_write = if contract_yaml_valid(&contract_path, &high_confidence_yaml) {
            high_confidence_yaml
        } else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => yaml,
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };

        if let Err(error) = fs::write(&contract_path, yaml_to_write) {
            result
                .skipped
                .push((repo.clone(), format!("write failed: {error}")));
            continue;
        }
        result.provisioned.push(repo.clone());
    }

    result
}

fn rewrite_workspace_repo_contracts(
    workspace_root: &Path,
    included: &[WorkspaceInitRepoSummary],
    missing_contract: &[WorkspaceInitRepoSummary],
) -> WorkspaceRepoRewriteResult {
    let mut result = WorkspaceRepoRewriteResult {
        rewritten: Vec::new(),
        skipped: Vec::new(),
    };
    let repos = included
        .iter()
        .chain(missing_contract.iter())
        .cloned()
        .collect::<Vec<_>>();

    for repo in repos {
        let repo_root = workspace_root.join(&repo.path);
        let contract_path = repo_root.join(DEFAULT_CONTRACT_FILE);
        let report = match detect_repo(&repo_root) {
            Ok(report) => report,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("detect failed: {error}")));
                continue;
            }
        };

        let high_confidence = report.high_confidence_contract();
        let high_confidence_yaml = match serde_yaml::to_string(&high_confidence) {
            Ok(yaml) => yaml,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("serialize failed: {error}")));
                continue;
            }
        };

        let yaml_to_write = if contract_yaml_valid(&contract_path, &high_confidence_yaml) {
            high_confidence_yaml
        } else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => yaml,
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };

        if contract_path.is_file()
            && let Err(error) = create_timestamped_backup(&contract_path)
        {
            result
                .skipped
                .push((repo.clone(), format!("backup failed: {error}")));
            continue;
        }

        if let Err(error) = fs::write(&contract_path, yaml_to_write) {
            result
                .skipped
                .push((repo.clone(), format!("write failed: {error}")));
            continue;
        }
        result.rewritten.push(repo);
    }

    result
}

fn contract_yaml_valid(path: &Path, yaml: &str) -> bool {
    parse_contract_str(path, yaml)
        .map_err(|error| error.to_string())
        .and_then(|contract| {
            validate_contract_with_path(&contract, Some(path)).map_err(|error| error.to_string())
        })
        .is_ok()
}

fn minimal_repo_contract_yaml(project_name: &str) -> Result<String, String> {
    let mut root = Mapping::new();
    root.insert(
        YamlValue::String(String::from("version")),
        YamlValue::Number(1u64.into()),
    );
    let mut project = Mapping::new();
    project.insert(
        YamlValue::String(String::from("name")),
        YamlValue::String(project_name.to_string()),
    );
    root.insert(
        YamlValue::String(String::from("project")),
        YamlValue::Mapping(project),
    );
    let yaml = serde_yaml::to_string(&YamlValue::Mapping(root))
        .map_err(|error| format!("failed to build minimal contract: {error}"))?;

    if !contract_yaml_valid(Path::new(DEFAULT_CONTRACT_FILE), &yaml) {
        return Err(String::from(
            "failed to build a valid minimal contract for auto-provision",
        ));
    }

    Ok(yaml)
}

#[derive(Clone)]
struct WorkspaceCandidate {
    name: String,
    path: String,
    has_contract: bool,
}

fn discover_workspace_candidates(workspace_root: &Path) -> Result<Vec<WorkspaceCandidate>, String> {
    let mut rel_paths = BTreeSet::new();
    collect_child_repo_dirs(workspace_root, workspace_root, &mut rel_paths)?;

    for group in ["apps", "services", "repos", "packages"] {
        let container = workspace_root.join(group);
        if container.is_dir() {
            collect_child_repo_dirs(workspace_root, &container, &mut rel_paths)?;
        }
    }

    let mut used_names = BTreeSet::new();
    let mut candidates = Vec::new();
    for rel_path in rel_paths {
        let repo_root = workspace_root.join(&rel_path);
        if !looks_like_repo_candidate(&repo_root) {
            continue;
        }
        let has_contract = repo_root.join(DEFAULT_CONTRACT_FILE).is_file();
        let name = make_workspace_repo_name(&rel_path, &mut used_names);
        candidates.push(WorkspaceCandidate {
            name,
            path: rel_path,
            has_contract,
        });
    }

    Ok(candidates)
}

fn collect_child_repo_dirs(
    workspace_root: &Path,
    parent: &Path,
    rel_paths: &mut BTreeSet<String>,
) -> Result<(), String> {
    let entries = fs::read_dir(parent)
        .map_err(|error| format!("failed to inspect `{}`: {error}", parent.display()))?;
    for entry in entries {
        let entry =
            entry.map_err(|error| format!("failed to inspect `{}`: {error}", parent.display()))?;
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if name.starts_with('.') {
            continue;
        }

        let rel = match path.strip_prefix(workspace_root) {
            Ok(rel) => rel,
            Err(_) => continue,
        };
        rel_paths.insert(path_to_contract_style(rel));
    }
    Ok(())
}

fn path_to_contract_style(path: &Path) -> String {
    path.components()
        .map(|component| component.as_os_str().to_string_lossy().into_owned())
        .collect::<Vec<_>>()
        .join("/")
}

fn make_workspace_repo_name(rel_path: &str, used_names: &mut BTreeSet<String>) -> String {
    let base = rel_path
        .rsplit('/')
        .next()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("repo")
        .to_string();
    if used_names.insert(base.clone()) {
        return base;
    }

    let mut normalized = rel_path.replace('/', "-");
    if normalized.is_empty() {
        normalized = String::from("repo");
    }
    if used_names.insert(normalized.clone()) {
        return normalized;
    }

    let mut suffix = 2;
    loop {
        let candidate = format!("{normalized}-{suffix}");
        if used_names.insert(candidate.clone()) {
            return candidate;
        }
        suffix += 1;
    }
}

fn looks_like_repo_candidate(repo_root: &Path) -> bool {
    if repo_root.join(DEFAULT_CONTRACT_FILE).is_file() || repo_root.join(".git").exists() {
        return true;
    }

    const MARKERS: [&str; 12] = [
        "package.json",
        "pyproject.toml",
        "requirements.txt",
        "go.mod",
        "Cargo.toml",
        "pom.xml",
        "build.gradle",
        "build.gradle.kts",
        "composer.json",
        "CMakeLists.txt",
        "mix.exs",
        "Project.toml",
    ];

    MARKERS
        .iter()
        .any(|marker| repo_root.join(marker).is_file())
}

#[derive(Clone, Debug)]
struct RunLogCaptureResult {
    logs: Option<ExecutionReceiptLogs>,
    warning: Option<String>,
}

#[derive(Clone, Debug)]
struct PreparedStreamingRunLogs {
    capture: RunLogCaptureResult,
    live_log: Option<StreamLogTee>,
}

fn capture_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    stdout: &str,
    stderr: &str,
    enabled: bool,
) -> RunLogCaptureResult {
    if !enabled {
        return RunLogCaptureResult {
            logs: None,
            warning: None,
        };
    }

    match write_durable_run_logs(contract_path, task_name, member, stdout, stderr) {
        Ok(logs) => RunLogCaptureResult {
            logs: Some(logs),
            warning: None,
        },
        Err(error) => RunLogCaptureResult {
            logs: None,
            warning: Some(format!("log capture failed: {error}")),
        },
    }
}

fn prepare_streaming_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    enabled: bool,
) -> PreparedStreamingRunLogs {
    if !enabled {
        return PreparedStreamingRunLogs {
            capture: RunLogCaptureResult {
                logs: None,
                warning: None,
            },
            live_log: None,
        };
    }

    match create_durable_run_log_paths(contract_path, task_name, member) {
        Ok((logs, stdout_path, stderr_path)) => {
            let stdout = File::create(&stdout_path).map_err(|error| {
                format!(
                    "failed to create stdout log `{}`: {error}",
                    compact_path(&stdout_path, ".")
                )
            });
            let stderr = File::create(&stderr_path).map_err(|error| {
                format!(
                    "failed to create stderr log `{}`: {error}",
                    compact_path(&stderr_path, ".")
                )
            });
            match (stdout, stderr) {
                (Ok(stdout), Ok(stderr)) => PreparedStreamingRunLogs {
                    capture: RunLogCaptureResult {
                        logs: Some(logs),
                        warning: None,
                    },
                    live_log: Some(StreamLogTee {
                        stdout: Arc::new(Mutex::new(stdout)),
                        stderr: Arc::new(Mutex::new(stderr)),
                    }),
                },
                (Err(error), _) | (_, Err(error)) => PreparedStreamingRunLogs {
                    capture: RunLogCaptureResult {
                        logs: None,
                        warning: Some(format!("log capture failed: {error}")),
                    },
                    live_log: None,
                },
            }
        }
        Err(error) => PreparedStreamingRunLogs {
            capture: RunLogCaptureResult {
                logs: None,
                warning: Some(format!("log capture failed: {error}")),
            },
            live_log: None,
        },
    }
}

fn capture_streaming_structured_error_logs(
    prepared_logs: &PreparedStreamingRunLogs,
    error_detail: &str,
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    enabled: bool,
) -> RunLogCaptureResult {
    if let (Some(logs), Some(live_log)) = (
        prepared_logs.capture.logs.clone(),
        prepared_logs.live_log.as_ref(),
    ) {
        match live_log.stderr.lock() {
            Ok(mut stderr) => match stderr.write_all(error_detail.as_bytes()) {
                Ok(()) => {
                    let _ = stderr.flush();
                    RunLogCaptureResult {
                        logs: Some(logs),
                        warning: prepared_logs.capture.warning.clone(),
                    }
                }
                Err(error) => RunLogCaptureResult {
                    logs: Some(logs),
                    warning: Some(format!("log capture failed: {error}")),
                },
            },
            Err(_) => RunLogCaptureResult {
                logs: Some(logs),
                warning: Some(String::from(
                    "log capture failed: durable log handle lock was poisoned",
                )),
            },
        }
    } else {
        capture_durable_run_logs(contract_path, task_name, member, "", error_detail, enabled)
    }
}

fn create_durable_run_log_paths(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
) -> Result<(ExecutionReceiptLogs, PathBuf, PathBuf), String> {
    let repo_root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let logs_root = repo_root.join(".ota").join("state").join("logs");
    fs::create_dir_all(&logs_root).map_err(|error| {
        format!(
            "failed to create log directory `{}`: {error}",
            compact_path(&logs_root, ".")
        )
    })?;

    let stamp = OffsetDateTime::now_utc()
        .format(&format_description!(
            "[year][month][day]-[hour][minute][second]-[subsecond digits:3]Z"
        ))
        .map_err(|error| format!("failed to format run log timestamp: {error}"))?;
    let task_slug = sanitize_log_component(task_name, "task");
    let member_suffix = member.map(|value| format!("-{}", sanitize_log_component(value, "member")));
    let run_id = format!(
        "{stamp}-{task_slug}{}-{}",
        member_suffix.unwrap_or_default(),
        std::process::id()
    );
    let run_dir = logs_root.join(run_id);
    fs::create_dir_all(&run_dir).map_err(|error| {
        format!(
            "failed to create run log directory `{}`: {error}",
            compact_path(&run_dir, ".")
        )
    })?;

    let stdout_path = run_dir.join("stdout.log");
    let stderr_path = run_dir.join("stderr.log");
    Ok((
        ExecutionReceiptLogs {
            dir: repo_relative_log_path(repo_root, &run_dir),
            stdout: repo_relative_log_path(repo_root, &stdout_path),
            stderr: repo_relative_log_path(repo_root, &stderr_path),
        },
        stdout_path,
        stderr_path,
    ))
}

fn write_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    stdout: &str,
    stderr: &str,
) -> Result<ExecutionReceiptLogs, String> {
    let (logs, stdout_path, stderr_path) =
        create_durable_run_log_paths(contract_path, task_name, member)?;
    fs::write(&stdout_path, stdout).map_err(|error| {
        format!(
            "failed to write stdout log `{}`: {error}",
            compact_path(&stdout_path, ".")
        )
    })?;
    fs::write(&stderr_path, stderr).map_err(|error| {
        format!(
            "failed to write stderr log `{}`: {error}",
            compact_path(&stderr_path, ".")
        )
    })?;

    Ok(logs)
}

fn sanitize_log_component(value: &str, fallback: &str) -> String {
    let mut output = value
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '-' })
        .collect::<String>();
    while output.contains("--") {
        output = output.replace("--", "-");
    }
    let output = output.trim_matches('-');
    if output.is_empty() {
        fallback.to_string()
    } else {
        output.to_string()
    }
}

fn repo_relative_log_path(repo_root: &Path, path: &Path) -> String {
    path.strip_prefix(repo_root)
        .map(|relative| relative.to_string_lossy().to_string())
        .unwrap_or_else(|_| compact_path(path, "."))
}

fn run_contract_targets(
    task_name: &str,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    members: &[String],
    task_inputs: &[String],
    show_receipt: bool,
    stream_output: bool,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    if members.is_empty() {
        let target = load_and_validate_target(resolved_path, None).map_err(|error| {
            render_run_contract_problem_failure(resolved_path, None, task_name, error)
        })?;
        return run_single_contract_target(
            task_name,
            overrides,
            None,
            target,
            task_inputs,
            show_receipt,
            stream_output,
            persist_logs,
        );
    }

    let mut stderr_sections = Vec::new();
    for member in members {
        let target =
            load_and_validate_target(resolved_path, Some(member.as_str())).map_err(|error| {
                render_run_contract_problem_failure(
                    resolved_path,
                    Some(member.as_str()),
                    task_name,
                    error,
                )
            })?;
        stderr_sections.push(run_single_contract_target(
            task_name,
            overrides,
            Some(member.as_str()),
            target,
            task_inputs,
            show_receipt,
            stream_output,
            persist_logs,
        )?);
    }

    Ok(stderr_sections.join("\n"))
}

fn run_single_contract_target(
    task_name: &str,
    overrides: ExecutionOverrides,
    member: Option<&str>,
    target: LoadedContractTarget,
    task_inputs: &[String],
    show_receipt: bool,
    stream_output: bool,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    let details_footer = task_use_details_footer(Some(&target.contract_path), member);
    if stream_output {
        return run_single_contract_target_streaming(
            task_name,
            overrides,
            member,
            target,
            task_inputs,
            show_receipt,
            &details_footer,
            persist_logs,
        );
    }

    run_single_contract_target_captured(
        task_name,
        overrides,
        member,
        target,
        task_inputs,
        show_receipt,
        &details_footer,
        persist_logs,
    )
}

fn run_single_contract_target_streaming(
    task_name: &str,
    overrides: ExecutionOverrides,
    member: Option<&str>,
    target: LoadedContractTarget,
    task_inputs: &[String],
    show_receipt: bool,
    details_footer: &str,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    let task_name = canonical_declared_task_name(&target.contract, task_name);
    let prepared_logs = prepare_streaming_durable_run_logs(
        &target.contract_path,
        task_name.as_str(),
        member,
        persist_logs,
    );
    match run_task_with_args_with_overrides_and_stream_capture(
        &target.contract,
        &target.contract_path,
        task_name.as_str(),
        task_inputs,
        overrides,
        true,
        prepared_logs.live_log.clone(),
    ) {
        Ok(outcome) if outcome.exit_code == 0 => {
            let log_capture = if prepared_logs.capture.logs.is_some() {
                prepared_logs.capture.clone()
            } else {
                capture_durable_run_logs(
                    &target.contract_path,
                    task_name.as_str(),
                    member,
                    &outcome.stdout,
                    &outcome.stderr,
                    persist_logs,
                )
            };
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                overrides,
                task_name.as_str(),
                member,
                &outcome.task_steps,
                &outcome.task_step_target_resolutions,
                &outcome.target_resolutions,
                &outcome.task_step_backend_fulfillments,
                outcome.backend_fulfillment.clone(),
                &outcome.task_step_shared_local_backends,
                outcome.shared_local_backend.clone(),
                outcome.exit_code,
                true,
                outcome.target.clone(),
                outcome.runtime.clone(),
                Some(task_use_details_step(Some(&target.contract_path), member)),
            );
            receipt.service_termination = outcome.service_termination.clone();
            apply_interrupted_run_classification(
                &mut receipt,
                outcome.service_termination.as_ref(),
                outcome.interrupted,
            );
            apply_run_log_capture_to_receipt(&mut receipt, log_capture);
            let mut output = String::new();
            if show_receipt {
                let receipt_text = render_execution_receipt_text(&receipt);
                if output.is_empty() {
                    output.push_str(receipt_text.trim_start_matches('\n'));
                } else {
                    output.push_str(&receipt_text);
                }
                output.push('\n');
            }
            output.push_str(&render_execution_receipt_summary_block(
                &receipt,
                Some(task_name.as_str()),
                "RUN SUMMARY",
            ));
            append_receipt_next_block(&mut output, &receipt);
            Ok(output)
        }
        Ok(outcome) => {
            let log_capture = if prepared_logs.capture.logs.is_some() {
                prepared_logs.capture.clone()
            } else {
                capture_durable_run_logs(
                    &target.contract_path,
                    task_name.as_str(),
                    member,
                    &outcome.stdout,
                    &outcome.stderr,
                    persist_logs,
                )
            };
            let failed_task_name = failed_task_name(&outcome.task_steps, task_name.as_str());
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                overrides,
                task_name.as_str(),
                member,
                &outcome.task_steps,
                &outcome.task_step_target_resolutions,
                &outcome.target_resolutions,
                &outcome.task_step_backend_fulfillments,
                outcome.backend_fulfillment.clone(),
                &outcome.task_step_shared_local_backends,
                outcome.shared_local_backend.clone(),
                outcome.exit_code,
                false,
                outcome.target.clone(),
                outcome.runtime.clone(),
                Some(format!(
                    "{}; {}",
                    format!(
                        "inspect task `{failed_task_name}` output and rerun `ota run {failed_task_name}`"
                    ),
                    details_footer
                )),
            );
            receipt.service_termination = outcome.service_termination.clone();
            apply_interrupted_run_classification(
                &mut receipt,
                outcome.service_termination.as_ref(),
                outcome.interrupted,
            );
            apply_run_log_capture_to_receipt(&mut receipt, log_capture);
            let summary = render_execution_receipt_summary_block(
                &receipt,
                Some(task_name.as_str()),
                "RUN SUMMARY",
            );
            let receipt_text = show_receipt.then(|| render_execution_receipt_text(&receipt));
            Err(RunCommandFailure {
                message: render_run_captured_failure_text(
                    &target.contract,
                    &target.contract_path,
                    &display_contract_target(&compact_contract_path(&target.contract_path), member),
                    &failed_task_name,
                    task_name.as_str(),
                    member,
                    overrides,
                    outcome.exit_code,
                    &outcome.stdout,
                    &outcome.stderr,
                    outcome.runtime.as_ref(),
                    outcome.service_termination.as_ref(),
                    outcome.interrupted,
                    receipt_text.as_deref(),
                    &summary,
                ),
                summary: None,
                exit_code: outcome.exit_code,
                receipt: None,
            })
        }
        Err(error) => {
            let error_detail = error.to_string();
            let log_capture = capture_streaming_structured_error_logs(
                &prepared_logs,
                &error_detail,
                &target.contract_path,
                task_name.as_str(),
                member,
                persist_logs,
            );
            let next_note = match &error {
                RunError::RuntimeListenerResolutionFailed {
                    task,
                    listener,
                    kind,
                } => runtime_listener_resolution_receipt_note(member, task, listener, kind),
                _ => format!(
                    "{}; {}",
                    format!("repair task `{task_name}` and rerun `ota run {task_name}`"),
                    details_footer
                ),
            };
            let error_target = match &error {
                RunError::PersistentContainerListenerBindConflict { container, .. } => {
                    Some(container.clone())
                }
                _ => None,
            };
            let error_backend_fulfillment = match &error {
                RunError::BackendRequirementsMissing { evidence, .. }
                | RunError::BackendFulfillmentFailed { evidence, .. } => Some(evidence.clone()),
                _ => None,
            };
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                overrides,
                task_name.as_str(),
                member,
                &[],
                &[],
                &[],
                &[],
                error_backend_fulfillment,
                &[],
                None,
                1,
                false,
                error_target,
                None,
                Some(next_note),
            );
            apply_run_log_capture_to_receipt(&mut receipt, log_capture);
            let summary = render_execution_receipt_summary_block(
                &receipt,
                Some(task_name.as_str()),
                "RUN SUMMARY",
            );
            let receipt_text = show_receipt.then(|| render_execution_receipt_text(&receipt));
            Err(RunCommandFailure {
                message: render_run_structured_error_text(
                    &target.contract,
                    &target.contract_path,
                    task_name.as_str(),
                    member,
                    overrides,
                    &error,
                    &summary,
                    receipt_text.as_deref(),
                ),
                summary: None,
                exit_code: 1,
                receipt: None,
            })
        }
    }
}

